window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[207]={"id":"207","numero":207,"titre":"Opacités et masses intra-thoraciques","objectifs":[{"id":"207-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une opacité pulmonaire chez l’enfant et l’adulte","contenu":"<p>Une <span class=\"kw-def\">opacité intra-parenchymateuse</span> est une opacité circonscrite, unique ou multiple, de densité <span class=\"kw-imagerie\">solide</span>, en <span class=\"kw-imagerie\">verre dépoli pur</span> ou <span class=\"kw-imagerie\">mixte</span>. La taille mesurée au <span class=\"kw-imagerie\">scanner</span> sépare 3 entités cliniquement distinctes — la <span class=\"kw-alerte\">RXT n'a aucune place pour la découverte d'un micronodule ou d'un nodule</span>, ni dans le <span class=\"kw-def\">dépistage</span> des cancers pulmonaires.</p>\n\n      <table >\n        <thead><tr><th>Entité</th><th>Taille</th><th>Mesure</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Micronodule</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 3 mm</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Nodule</span></strong></td>\n            <td><span class=\"kw-chiffre\">3–30 mm</span></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Nodule</span> <span class=\"kw-chiffre\">≤ 10 mm</span> :</strong> moyenne entre grand axe et petit axe<br>\n              <strong>Nodule &gt;<span class=\"kw-chiffre\"> 10 mm</span> ou rond :</strong> plus grand <span class=\"kw-clinique\">diamètre</span> suffit\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Masse</span></strong></td>\n            <td><span class=\"kw-chiffre\">&gt; 3 cm</span></td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><span class=\"kw-clinique\">Les</span> nodules solides sont de plus en plus appréciés par leur <span class=\"kw-def\">volume</span> (mesure assistée par ordinateur, exprimé en mm³). Les opacités intra-parenchymateuses sont à distinguer des <span class=\"kw-def\">opacités rondes extra-parenchymateuses</span> développées à partir de la paroi thoracique ou de la plèvre (angle de raccord obtus <span class=\"kw-bio\">vs</span> aigu).</p>\n\n      <h5>Circonstances de découverte</h5>\n      <ul>\n        <li><strong>Bilan médical orienté :</strong> bilan d'une maladie respiratoire (suite de pneumopathie, BPCO, <span class=\"kw-clinique\">toux</span>, exposition à l'amiante) ou <span class=\"kw-def\">bilan d'extension</span> d'un cancer / maladie de système — interprétation à l'aune du <span class=\"kw-def\">terrain</span>.</li>\n        <li><strong>Découverte fortuite ou <span class=\"kw-def\">dépistage</span> :</strong> <span class=\"kw-imagerie\">angioscanner</span> des troncs supra-aortiques, <span class=\"kw-imagerie\">scanner</span> abdominal, ou dépistage opportuniste chez sujet éligible.</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Diagnostic étiologique</span> — examens morphologiques</h5>\n      <table >\n        <thead><tr><th>Examen</th><th>Place / indications</th><th>Pièges à connaître</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie pré-thérapeutique</strong></td>\n            <td>\n              <strong>Fonction rénale :</strong> autorise l'injection de <span class=\"kw-ttt\">PDC</span><br>\n              <strong>Hémostase :</strong> <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">TP</span> ; <span class=\"kw-bio\">TCA</span> pour prélèvements biopsiques<br>\n              <strong>Bilan complémentaire :</strong> <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">calcémie</span> ; albuminémie\n            </td>\n            <td><span class=\"kw-alerte\">Dosage des marqueurs sériques NON recommandé</span> (aucune indication, à savoir pour <span class=\"kw-clinique\">les</span> QCM)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RXT</span> (face + profil)</strong></td>\n            <td>\n              <strong>Signes directs :</strong> opacité hilaire/péri-hilaire (limites externes irrégulières, parfois spiculée) ; opacité périphérique (arrondie non systématisée, dense, parfois excavée par <span class=\"kw-clinique\">nécrose</span>)<br>\n              <strong>Signes indirects :</strong> <span class=\"kw-imagerie\">atélectasie</span> segmentaire/lobaire (obstruction bronchique) ; épanchement pleural ; <span class=\"kw-imagerie\">adénopathies hilaires/médiastinales</span> ; lyse costale/vertébrale ; <span class=\"kw-imagerie\">ascension d'une coupole</span> (paralysie phrénique)\n            </td>\n            <td><span class=\"kw-alerte\">Place marginale</span> dans le diagnostic de cancer pulmonaire ; <span class=\"kw-alerte\">une RXT normale n'élimine pas le diagnostic</span> mais reste rare en cas de cancer avéré (&lt;<span class=\"kw-chiffre\"> 5 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoracique injectée</strong></td>\n            <td>\n              <strong>Topographie :</strong> centrale/hilaire ou périphérique<br>\n              <strong>Caractérisation :</strong> systématisé/rétractile ou non ; rapports avec paroi/structures avoisinantes<br>\n              <strong>Imagerie MIP :</strong> meilleur dénombrement des nodules par sommation des coupes<br>\n              <strong>Facteurs associés :</strong> plaques pleurales asbestosiques ; <span class=\"kw-clinique\">adénopathies</span> médiastinales\n            </td>\n            <td>Examen pivot du diagnostic</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TEP</span> au <span class=\"kw-bio\">18-FDG</span></strong></td>\n            <td>\n              <strong>Indications :</strong> <span class=\"kw-clinique\">nodule</span> de nature incertaine (<span class=\"kw-chiffre\">RVP ≈ 4</span>) ; <span class=\"kw-def\">bilan d'extension</span> à distance d'une tumeur éligible à un traitement local ; staging médiastinal d'un cancer à priori opérable\n            </td>\n            <td>\n              <strong>Faux négatifs :</strong> <span class=\"kw-clinique\">nodule</span> <span class=\"kw-chiffre\">&lt; 1 cm</span> ; nodule en <span class=\"kw-imagerie\">verre dépoli pur</span><br>\n              <strong>Faux positifs :</strong> foyers <span class=\"kw-etio\">infectieux</span> chroniques (actinomycose, nocardiose) ; mycobactérioses ; aspergilloses ; <span class=\"kw-clinique\">sarcoïdose</span><br>\n              <strong>Fixations non pathologiques :</strong> vésicale ; colique ; cardiaque ; cérébrale\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie métabolique <span class=\"kw-ttt\">DOTATOC</span></strong></td>\n            <td><span class=\"kw-imagerie\">Scintigraphie</span> des récepteurs de la somatostatine pour <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">tumeurs carcinoïdes bronchiques</span></td>\n            <td>Ne dispense pas de la <span class=\"kw-ttt\">biopsie</span> (diagnostic) ; exérèse économe en parenchyme requise pour le traitement</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Diagnostic histo-pathologique — choix de la technique selon la localisation</h5>\n      <table >\n        <thead><tr><th>Localisation</th><th>Technique de référence</th><th>Anesthésie</th><th>Complications / <span class=\"kw-ci\">contre-indications</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Systématique</strong></td>\n            <td><span class=\"kw-ttt\">Fibroscopie bronchique</span> (<span class=\"kw-imagerie\">bronchoscopie</span> souple)</td>\n            <td>Locale ou générale</td>\n            <td>\n              <strong><span class=\"kw-ci\">Contre-indications</span> :</strong> <span class=\"kw-ci\">hypoxémie réfractaire</span> à <span class=\"kw-ttt\">oxygénothérapie</span> ; <span class=\"kw-ci\">anomalies majeures de la coagulation</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lésion</span> centrale</strong> (1/3 central, autour de la carène)</td>\n            <td><span class=\"kw-ttt\">Fibroscopie bronchique</span> (biopsies bronchiques : minimum 3-5 + biopsies systématiques de l'éperon et de la carène)</td>\n            <td>Locale ou générale</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lésion</span> périphérique</strong> (1/3 périphérique)</td>\n            <td>\n              <strong>Privilégier :</strong> <span class=\"kw-ttt\">ponction-biopsie transpariétale à l'aiguille</span> (sous <span class=\"kw-imagerie\">TDM</span>, parfois échoguidée si <span class=\"kw-def\">contact</span> pariétal)<br>\n              <strong>Alternative :</strong> vidéo-thoracoscopie exploratrice\n            </td>\n            <td>Locale</td>\n            <td>\n              <strong>Sensibilité :</strong> ~<span class=\"kw-chiffre\">90 %</span> ; négativité (<span class=\"kw-chiffre\">10–15 %</span>) <span class=\"kw-alerte\">n'élimine pas le diagnostic</span><br>\n              <strong>Complications :</strong> <span class=\"kw-clinique\">hémoptysie</span> (rare) ; <span class=\"kw-alerte\">pneumothorax 10 %</span> (souvent minime mais mal toléré si <span class=\"kw-ci\">insuffisance respiratoire</span> — d'où évaluation spirométrique préalable)<br>\n              <strong>Distracteur QCM :</strong> <span class=\"kw-alerte\">PAS d'épanchement pleural</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lésion</span> intermédiaire</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">Fibroscopie</span> bronchique ± <span class=\"kw-ttt\">ponction</span> transpariétale ± thoracotomie exploratrice\n            </td>\n            <td>Variable</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Adénopathies</span> au <span class=\"kw-def\">contact</span> de la trachée</strong></td>\n            <td>\n              <strong><span class=\"kw-imagerie\">Fibroscopie</span></strong> avec abord ganglionnaire à l'aiguille ; <strong><span class=\"kw-imagerie\">écho-endoscopie</span></strong> (EBUS / <span class=\"kw-imagerie\">EUS</span>) ; <strong>médiastinoscopie</strong>\n            </td>\n            <td>Générale</td>\n            <td>EBUS = tend à remplacer la médiastinoscopie en <span class=\"kw-chiffre\">1ère intention</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Lésion</span> à distance</strong></td>\n            <td>\n              <strong>À prioriser :</strong> <span class=\"kw-ttt\">biopsie</span> d'<span class=\"kw-clinique\">adénopathie</span> sus-claviculaire ou de métastase cutanée (sans complications, affirment N3 et <span class=\"kw-chiffre\">M1</span> respectivement)<br>\n              <strong>Autres :</strong> biopsie métastase hépatique ; biopsie ostéolytique ; biopsie cérébrale prévalente ; biopsie pleurale (si épanchement abondant)\n            </td>\n            <td>Variable</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> La <span class=\"kw-ttt\">fibroscopie bronchique</span> est <strong>systématique en cas de suspicion de cancer bronchique</strong>, même en cas de cancer périphérique où elle peut être normale — elle ne sert pas qu'à atteindre la <span class=\"kw-clinique\">lésion</span>, mais aussi à rechercher des lésions radio-occultes proximales. Une <span class=\"kw-imagerie\">fibroscopie</span> normale n'élimine PAS le diagnostic.\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Aucun argument radiologique ne peut être formel.</strong> <span class=\"kw-alerte\">Seule l'histologie permet un diagnostic de certitude.</span> Tous <span class=\"kw-clinique\">les</span> algorithmes radio-cliniques (Fleischner, etc.) sont rang C et n'orientent que la décision de <span class=\"kw-ttt\">biopsie</span>.\n      </div>\n\n      <h5>Étiologies — vue d'ensemble</h5>\n      <table >\n        <thead><tr><th>Groupe</th><th>Entités</th><th>Signes orientant</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumeurs malignes</strong></td>\n            <td>\n              <strong>Primitifs :</strong> <span class=\"kw-def\">cancers bronchopulmonaires</span> (le plus souvent <span class=\"kw-clinique\">nodule</span> pulmonaire solitaire ± calcifications dans <span class=\"kw-clinique\">les</span> tumeurs neuro-endocrines)<br>\n              <strong>Secondaires :</strong> <span class=\"kw-def\">métastases pulmonaires</span> (opacités rondes, uniques ou multiples, contours réguliers)\n            </td>\n            <td><span class=\"kw-def\">Terrain</span> (tabac, exposition amiante) ; cinétique évolutive ; spiculation</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeurs bénignes</strong> (<span class=\"kw-chiffre\">~10 %</span> des nodules)</td>\n            <td>\n              <strong><span class=\"kw-def\">Hamartochondrome</span></strong> = tumeur bénigne la plus fréquente : aspect <span class=\"kw-imagerie\">TDM</span> pathognomonique en <span class=\"kw-imagerie\">« pop-corn »</span> (calcifications + densités graisseuses) ; <span class=\"kw-imagerie\">TEP</span>-FDG négative<br>\n              <strong>Ganglion intra-pulmonaire :</strong> <span class=\"kw-clinique\">nodule</span> tissulaire homogène <span class=\"kw-chiffre\">&lt; 10 mm</span>, triangulaire/ovalaire, à <span class=\"kw-chiffre\">&lt; 15 mm de la plèvre</span> et en dessous du niveau de la carène\n            </td>\n            <td>Opacité unique, sphérique, contour régulier</td>\n          </tr>\n          <tr>\n            <td><strong>Infectieuses</strong></td>\n            <td>\n              <strong>Cavités à pyogènes :</strong> <span class=\"kw-def\">abcès pulmonaire</span> (contexte aigu fébrile + vomique ; contours flous à cavité nette ± niveau hydro-aérique)<br>\n              <strong><span class=\"kw-clinique\">Cavernes tuberculeuses</span> :</strong> prédominance apicale ; contamination familiale ; <span class=\"kw-clinique\">IDR</span>/IGRA+<br>\n              <strong><span class=\"kw-clinique\">Tuberculome</span> :</strong> foyers calcifiés concentriques (peuvent justifier prélèvements mycobactériologiques)<br>\n              <strong><span class=\"kw-clinique\">Aspergillome</span> :</strong> aspect <span class=\"kw-imagerie\">TDM</span> caractéristique en <span class=\"kw-imagerie\">« image en grelot »</span> au sein d'une cavité préexistante ; <span class=\"kw-bio\">sérologie</span> aspergillaire +<br>\n              <strong><span class=\"kw-clinique\">Kyste hydatique</span> :</strong> Afrique du Nord / Amérique latine / Europe Est / Chine ; densité hydrique ; <span class=\"kw-imagerie\">membrane flottante</span> ± croissant gazeux<br>\n              <strong>Bactéries filamenteuses</strong> (<em>Actinomyces</em> porte dentaire ; <em>Nocardia</em>) : croissance lente, peuvent mimer un cancer\n            </td>\n            <td>Contexte ; topographie ; aspect cavitaire</td>\n          </tr>\n          <tr>\n            <td><strong>Autres causes</strong></td>\n            <td>\n              <strong>Connectivites/vascularites :</strong> granulomatose avec polyangéite (<span class=\"kw-clinique\">Wegener</span>) ; nodules rhumatoïdes<br>\n              <strong>Vasculaires :</strong> <span class=\"kw-def\">malformations artério-veineuses</span> (souvent multiples ; intégrées au cadre de la maladie de Rendu-Osler)<br>\n              <strong>Pariéto-pulmonaires :</strong> atélectasie ronde ; masses pseudo-tumorales silicotiques\n            </td>\n            <td>Contexte rhumatologique/exposition</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-opacite-lacher-de-ballon.png\" alt=\"Radiographie de thorax de face montrant de multiples opacités arrondies bien limitées des deux hémithorax (aspect en lâcher de ballon) correspondant à des nodules pulmonaires multiples métastatiques, avec une chambre implantable visible\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie de thorax de face</span>. <span class=\"kw-radio\">Multiples opacités arrondies bien limitées des 2 hémithorax</span> (aspect en « lâcher de ballon ») : <span class=\"kw-def\">nodules pulmonaires multiples (métastases pulmonaires)</span>. Noter la <span class=\"kw-radio\">chambre implantable</span>. Rappel : une <span class=\"kw-radio\">opacité pulmonaire</span> est une augmentation de densité du parenchyme, localisée ou diffuse, bien ou mal limitée. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 154 — Infection bronchopulmonaire communautaire · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 210 — Pneumopathie interstitielle diffuse</em></p>","frequence":4},{"id":"207-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une fracture de côte chez l’enfant et l’adulte","contenu":"<p>La <span class=\"kw-def\">fracture de côte</span> est une <span class=\"kw-clinique\">lésion</span> fréquente en traumatologie thoracique. Le diagnostic est essentiellement <span class=\"kw-radio\">radiographique</span>, mais l'enjeu réel est moins la fracture elle-même que la recherche des <span class=\"kw-alerte\">complications associées</span> (pneumothorax, hémothorax, contusion pulmonaire) et l'évaluation de la <span class=\"kw-alerte\">gravité mécanique</span> (volet costal).</p>\n\n      <h5>Sémiologie radiologique</h5>\n      <table >\n        <thead><tr><th>Modalité</th><th>Sémiologie</th><th>Indications / limites</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RXT</span> face + profil</strong></td>\n            <td>\n              <strong>Signe direct :</strong> <span class=\"kw-imagerie\">trait de fracture costale</span> hypodense, discontinuité corticale, déplacement variable<br>\n              <strong>Signes indirects :</strong> <span class=\"kw-imagerie\">cal osseux</span> visible à distance ; <span class=\"kw-imagerie\">décalage des arcs costaux</span> ; emphysème sous-cutané associé\n            </td>\n            <td>Examen de <span class=\"kw-chiffre\">première intention</span> ; <span class=\"kw-alerte\">sensibilité limitée</span> (~<span class=\"kw-chiffre\">50 %</span>) — fracture non déplacée souvent ratée, ne pas s'en contenter si forte suspicion clinique</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoracique</strong></td>\n            <td>\n              <strong>Indications :</strong> doute diagnostique sur <span class=\"kw-imagerie\">RXT</span> ; suspicion de complications (volet costal, hémothorax, contusion) ; polytraumatisé<br>\n              <strong>Apport :</strong> identification précise du nombre et de la topographie des fractures ; recherche des lésions parenchymateuses et pleurales associées\n            </td>\n            <td>Référence pour le bilan lésionnel complet en cas de traumatisme thoracique sévère</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Complications à rechercher systématiquement</h5>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Pneumothorax</strong></td><td>Effraction pleurale par esquille osseuse</td><td><span class=\"kw-imagerie\">Hyperclarté avasculaire</span> ; ligne pleurale décollée</td></tr>\n          <tr><td><strong>Hémothorax</strong></td><td>Section d'un vaisseau intercostal</td><td><span class=\"kw-imagerie\">Opacité pleurale déclive</span> ; comblement du cul-de-sac costo-diaphragmatique</td></tr>\n          <tr><td><strong>Contusion pulmonaire</strong></td><td><span class=\"kw-clinique\">Lésion</span> directe du parenchyme</td><td><span class=\"kw-imagerie\">Opacité alvéolaire mal limitée</span> en regard du foyer fracturaire ; non systématisée</td></tr>\n          <tr><td><strong>Volet costal</strong></td><td><span class=\"kw-alerte\">≥ 3 côtes fracturées en 2 points</span></td><td>Mobilité paradoxale clinique ; <span class=\"kw-alerte\">urgence vitale</span> par <span class=\"kw-ci\">insuffisance respiratoire</span> restrictive</td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-fracture-cote.png\" alt=\"Deux radiographies du gril costal gauche chez le même patient montrant une fracture de l'arc moyen de la 8ème côte gauche avec un discret déplacement\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies du gril costal gauche</span> (même patient). <span class=\"kw-radio\">Fracture de l'arc moyen de la 8ᵉ côte gauche</span>, avec discret déplacement. L'<span class=\"kw-def\">incidence</span> centrée sur le gril costal augmente la sensibilité par rapport à la <span class=\"kw-imagerie\">RXT</span> standard. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>Particularité pédiatrique — <span class=\"kw-alerte\">drapeau rouge</span>.</strong> Chez l'enfant, <span class=\"kw-clinique\">les</span> côtes sont <span class=\"kw-imagerie\">flexibles</span> : une fracture costale survient pour des traumatismes de forte intensité. <span class=\"kw-alerte\">Une fracture de côte chez un nourrisson ou un jeune enfant sans contexte traumatique évident doit faire suspecter une maltraitance</span> (<span class=\"kw-clinique\">syndrome de l</span>'enfant secoué, sévices physiques) et déclencher un <span class=\"kw-def\">signalement</span>.\n      </div>","frequence":1},{"id":"207-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un épanchement pleural liquidien chez l’enfant et l’adulte","contenu":"<p>L'<span class=\"kw-def\">épanchement pleural liquidien</span> se traduit par une <span class=\"kw-imagerie\">opacité dense, homogène et déclive</span>. Le diagnostic est posé sur l'imagerie puis confirmé par <span class=\"kw-ttt\">ponction pleurale exploratrice</span> ; l'analyse cytochimique (<span class=\"kw-def\">critères de</span> Light) et la prise en charge détaillée relèvent de l'item 206 dédié.</p>\n\n      <h5>Sémiologie radiologique</h5>\n      <table >\n        <thead><tr><th>Modalité</th><th>Signes cardinaux</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RXT</span></strong></td>\n            <td>\n              <span class=\"kw-radio\">Opacité homogène déclive</span> à <span class=\"kw-radio\">ligne bordante supérieure concave</span> en haut et en dedans (<span class=\"kw-radio\">ligne de Damoiseau</span>)<br>\n              <span class=\"kw-radio\">Effacement du cul-de-sac pleural costo-diaphragmatique</span><br>\n              Si abondant : <span class=\"kw-alerte\">déplacement médiastinal controlatéral</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoracique</strong></td>\n            <td>Précise le <span class=\"kw-imagerie\">volume</span>, le <span class=\"kw-imagerie\">cloisonnement</span>, un <span class=\"kw-imagerie\">épaississement pleural</span> associé (mésothéliome, carcinose pleurale)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Conduite diagnostique</h5>\n      <p><span class=\"kw-def\">Diagnostic positif</span> radiologique puis <span class=\"kw-ttt\">ponction pleurale exploratrice</span> (analyse cytochimique : <strong><span class=\"kw-def\">critères de</span> Light</strong> → cf item 206 dédié). <span class=\"kw-ttt\">Drainage</span> si volume important ou symptomatique.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pièges.</strong>\n        <ul>\n          <li>Différencier de l'opacité homogène pulmonaire (<span class=\"kw-etio\">atélectasie complète d'un poumon</span>) sur le caractère <strong>NON rétractile</strong> et la <strong>déclivité</strong> de l'épanchement.</li>\n          <li>Le <span class=\"kw-radio\">scanner en décubitus latéral</span> peut détecter un épanchement &lt;<span class=\"kw-chiffre\"> 50 mL</span>.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 206 — Epanchement pleural</em></p>","frequence":0},{"id":"207-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un épanchement pleural gazeux chez l’enfant et l’adulte","contenu":"<div class=\"callout callout-warn\">\n        Sémiologie radiographique du pneumothorax — la prise en charge détaillée (<span class=\"kw-ttt\">drainage</span>, indications) relève de l'<strong>item 206</strong> dédié.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-pneumothorax.png\" alt=\"Deux radiographies de thorax de face : à gauche pneumothorax droit de moyenne abondance avec croissant clair avasculaire périphérique et ligne bordante pleurale ; à droite pneumothorax droit complet compressif avec hyperclarté diffuse de l'hémithorax droit, poumon rétracté au hile et déviation médiastinale controlatérale\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span>. <strong>À gauche :</strong> <span class=\"kw-def\">pneumothorax droit de moyenne abondance</span> — <span class=\"kw-radio\">croissant clair avasculaire périphérique</span> et <span class=\"kw-radio\">ligne bordante pleurale</span> (plèvre viscérale décollée de la plèvre pariétale). <strong>À droite :</strong> <span class=\"kw-alerte\">pneumothorax droit complet compressif</span> — <span class=\"kw-radio\">hyperclarté diffuse de l'hémithorax droit</span>, <span class=\"kw-radio\">poumon entièrement décollé et rétracté au hile</span>, <span class=\"kw-radio\">déviation médiastinale controlatérale</span> signant le caractère compressif. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 206 — Epanchement pleural · 360 — Pneumothorax</em></p>","frequence":1},{"id":"207-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un syndrome alvéolaire","contenu":"<p>Le <span class=\"kw-def\">syndrome alvéolaire</span> traduit un <span class=\"kw-imagerie\">comblement des espaces alvéolaires</span> par du liquide (eau, sang, pus) ou des cellules. C'est l'un des trois grands syndromes radiologiques pulmonaires (avec interstitiel et bronchique) — sa reconnaissance oriente immédiatement vers un cadre étiologique précis.</p>\n\n      <h5>Sémiologie radiologique</h5>\n      <table >\n        <thead><tr><th>Modalité</th><th>Signes cardinaux</th><th>Signes associés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RXT</span></strong></td>\n            <td>\n              <strong>Opacités :</strong> <span class=\"kw-imagerie\">floues, à limites mal définies</span>, <span class=\"kw-imagerie\">confluentes</span><br>\n              <strong>Topographie :</strong> souvent <span class=\"kw-imagerie\">systématisée</span> (segmentaire ou lobaire), parfois diffuse bilatérale<br>\n              <strong>Bronchogramme aérique :</strong> <span class=\"kw-imagerie\">visualisation des bronches aérées</span> contrastant avec l'opacité alvéolaire — signe quasi-pathognomonique\n            </td>\n            <td>Effacement des contours médiastinaux ou diaphragmatiques (signe de la silhouette) ; absence de rétraction (≠ atélectasie)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoracique</strong></td>\n            <td>\n              <strong>Verre dépoli :</strong> comblement alvéolaire partiel<br>\n              <strong>Condensations :</strong> comblement alvéolaire complet effaçant <span class=\"kw-clinique\">les</span> vaisseaux<br>\n              <strong>Bronchogramme aérique <span class=\"kw-imagerie\">TDM</span> :</strong> bronches perméables traversant la zone condensée\n            </td>\n            <td>Distribution gravito-dépendante (<span class=\"kw-alerte\">OAP</span>), lobaire (pneumonie), diffuse (<span class=\"kw-alerte\">SDRA</span>, hémorragie)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Étiologies hiérarchisées</h5>\n      <table >\n        <thead><tr><th>Cause</th><th>Contexte clinique</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Pneumonie infectieuse</strong></td>\n            <td><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">toux</span>, crachats purulents, <span class=\"kw-bio\">syndrome inflammatoire</span></td>\n            <td>Étiologie la plus fréquente ; condensation lobaire (<span class=\"kw-etio\">pneumocoque</span>) ou bronchopneumonie multifocale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">OAP</span> cardiogénique</strong></td>\n            <td><span class=\"kw-clinique\">Dyspnée</span> aiguë, <span class=\"kw-clinique\">orthopnée</span>, <span class=\"kw-clinique\">crépitants bilatéraux</span></td>\n            <td>Distribution <span class=\"kw-imagerie\">péri-hilaire en ailes de papillon</span> ; cardiomégalie ; lignes B de Kerley ; <span class=\"kw-bio\">BNP / NT-proBNP ↑</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie intra-alvéolaire</strong></td>\n            <td><span class=\"kw-clinique\">Hémoptysies</span> + anémie aiguë + infiltrats diffus</td>\n            <td>Vascularites (Goodpasture, <span class=\"kw-clinique\">GPA</span>), troubles de l'hémostase, lupus ; <span class=\"kw-bio\">LBA hémorragique avec score de Golde élevé</span></td>\n          </tr>\n          <tr>\n            <td><strong>Adénocarcinome lépidique</strong></td>\n            <td><span class=\"kw-clinique\">Toux</span> chronique <span class=\"kw-alerte\">avec bronchorrhée</span>, <span class=\"kw-def\">terrain</span> non spécifique</td>\n            <td>Forme particulière de cancer pulmonaire ; <span class=\"kw-imagerie\">condensations persistantes</span> résistantes aux antibiotiques</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">SDRA</span></strong></td>\n            <td>Contexte de <span class=\"kw-alerte\">sepsis</span>, polytraumatisme, inhalation</td>\n            <td>Infiltrats <span class=\"kw-imagerie\">bilatéraux diffus</span> ; pas d'argument pour <span class=\"kw-alerte\">OAP</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-syndrome-alveolaire.png\" alt=\"Deux radiographies de thorax de face : à gauche syndrome alvéolaire unilatéral correspondant à une pneumopathie franche lobaire aiguë du lobe moyen avec opacité dense à limite supérieure nette et bronchogramme aérique ; à droite syndrome alvéolaire bilatéral en ailes de papillon correspondant à un œdème aigu pulmonaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span>. <strong>À gauche :</strong> <span class=\"kw-radio\">syndrome alvéolaire unilatéral</span> — opacité dense inférieure droite à <span class=\"kw-radio\">limite supérieure nette (scissurale)</span> avec <span class=\"kw-radio\">bronchogramme aérique</span>, correspondant à une <span class=\"kw-def\">PFLA du lobe moyen</span>. <strong>À droite :</strong> <span class=\"kw-radio\">syndrome alvéolaire bilatéral</span> — opacités <span class=\"kw-radio\">péri-hilaires en « ailes de papillon »</span>, correspondant à un <span class=\"kw-def\">OAP</span>. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/tdm-syndrome-alveolaire.png\" alt=\"TDM thoracique en coupe axiale, fenêtre parenchymateuse, montrant un syndrome alvéolaire bilatéral : condensation du lobe supérieur droit effaçant les vaisseaux avec bronchogramme aérique, verre dépoli laissant voir les vaisseaux, et condensation du lobe supérieur gauche\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM thoracique</span>, coupe axiale, fenêtre parenchymateuse — <span class=\"kw-radio\">syndrome alvéolaire bilatéral</span>. <span class=\"kw-radio\">Condensation</span> (opacité effaçant <span class=\"kw-clinique\">les</span> contours vasculaires) avec <span class=\"kw-radio\">bronchogramme aérique</span> ; <span class=\"kw-radio\">verre dépoli</span> (opacité n'effaçant pas les vaisseaux) = comblement alvéolaire incomplet. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire · 226 — Thrombose veineuse profonde - EP · 309 — Tumeurs du poumon</em></p>","frequence":0},{"id":"207-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un syndrome interstitiel","contenu":"<p>Le <span class=\"kw-def\">syndrome interstitiel</span> traduit une <span class=\"kw-imagerie\">infiltration du tissu interstitiel pulmonaire</span> (parois alvéolaires, septa, espace péri-broncho-vasculaire). C'est l'un des trois grands syndromes radiologiques avec l'alvéolaire et le bronchique. Objectif <span class=\"kw-chiffre\">4 ⭐ EDN</span> — fréquence élevée au concours.</p>\n\n      <h5>Sémiologie radiographique (<span class=\"kw-imagerie\">RXT</span>)</h5>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span> élémentaire</th><th>Sémiologie</th><th>Valeur d'orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Opacités réticulaires</strong></td>\n            <td><span class=\"kw-imagerie\">Fines lignes intriquées</span> dessinant un maillage</td>\n            <td>Évoque une atteinte septale ou fibrosante</td>\n          </tr>\n          <tr>\n            <td><strong>Opacités nodulaires</strong></td>\n            <td><span class=\"kw-imagerie\">Micronodules &lt; 3 mm</span> ou nodules diffus</td>\n            <td>Évoque granulomatose (<span class=\"kw-clinique\">sarcoïdose</span>, <span class=\"kw-etio\">tuberculose</span> miliaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Lignes B de Kerley</strong></td>\n            <td><span class=\"kw-imagerie\">Lignes horizontales sous-pleurales</span> de <span class=\"kw-chiffre\">1–2 cm</span>, perpendiculaires à la paroi</td>\n            <td>Évoque <span class=\"kw-clinique\">OAP</span> chronique, lymphangite carcinomateuse</td>\n          </tr>\n          <tr>\n            <td><strong>Comblement scissural</strong></td>\n            <td><span class=\"kw-imagerie\">Épaississement linéaire de la grande/petite scissure</span></td>\n            <td>Signe d'<span class=\"kw-ttt\">infiltration</span> interstitielle péri-scissurale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><span class=\"kw-alerte\">La RXT a une sensibilité limitée</span> — une <span class=\"kw-imagerie\">RXT</span> normale n'élimine pas un syndrome interstitiel. Le diagnostic repose sur la <strong><span class=\"kw-imagerie\">TDM</span>-HR sans injection</strong> (examen de référence).</p>\n\n      <h5><span class=\"kw-imagerie\">TDM</span>-HR — <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>6</span> l</span>ésions élémentaires</h5>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Sémiologie</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Verre dépoli</strong></td><td><span class=\"kw-imagerie\">Augmentation de densité préservant la trame</span> vasculaire et bronchique</td><td>Inflammation active (PHS aiguë, PINS, hémorragie)</td></tr>\n          <tr><td><strong>Condensations</strong></td><td><span class=\"kw-imagerie\">Effacement des vaisseaux</span> par comblement alvéolaire</td><td>Pneumonie organisée (POC), adénocarcinome lépidique</td></tr>\n          <tr><td><strong>Micronodules</strong></td><td><span class=\"kw-imagerie\">Nodules &lt; 3 mm</span> de distribution variable</td><td><span class=\"kw-clinique\">Sarcoïdose</span> (péri-lymphatique), miliaire TB (random), PHS (centro-lobulaire)</td></tr>\n          <tr><td><strong>Réticulations</strong></td><td><span class=\"kw-imagerie\">Maillage fin</span> intra-lobulaire</td><td>Premier <span class=\"kw-def\">stade</span> des fibroses</td></tr>\n          <tr><td><strong>Rayon de miel</strong> (honeycombing)</td><td><span class=\"kw-imagerie\">Kystes sous-pleuraux empilés</span> de taille croissante en profondeur</td><td><span class=\"kw-alerte\">Marqueur de fibrose irréversible</span> — fibrose pulmonaire idiopathique (FPI) +++</td></tr>\n          <tr><td><strong>Bronchectasies par traction</strong></td><td><span class=\"kw-imagerie\">Dilatation des bronches</span> par traction du parenchyme fibreux</td><td>Marqueur de fibrose ; associé au rayon de miel dans la PIC</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Profils topographiques discriminants</h5>\n      <table >\n        <thead><tr><th>Profil</th><th>Topographie <span class=\"kw-imagerie\">TDM</span>-HR</th><th>Étiologie évocatrice</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>PIC</strong> (Pneumopathie Interstitielle Commune)</td>\n            <td><span class=\"kw-imagerie\">Basale, sous-pleurale, bilatérale</span> + rayon de miel + bronchectasies de traction</td>\n            <td><span class=\"kw-clinique\">FPI</span> (fibrose pulmonaire idiopathique)</td>\n          </tr>\n          <tr>\n            <td><strong>PINS</strong> (Pneumopathie Interstitielle Non Spécifique)</td>\n            <td><span class=\"kw-imagerie\">Préservation sous-pleurale</span> ; verre dépoli prédominant ; symétrique</td>\n            <td>Connectivites (<span class=\"kw-clinique\">sclérodermie</span>, polymyosite)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Sarcoïdose</span></strong></td>\n            <td><span class=\"kw-imagerie\">Micronodules péri-lymphatiques</span> à prédominance des lobes supérieurs ; <span class=\"kw-imagerie\">adénopathies hilaires bilatérales symétriques</span></td>\n            <td><span class=\"kw-clinique\">Sarcoïdose</span> <span class=\"kw-def\">stade</span> I à IV</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-syndrome-interstitiel.png\" alt=\"Trois radiographies de thorax de face de patients distincts montrant des syndromes interstitiels : opacités bilatérales diffuses non systématisées, réticulaires et micronodulaires, avec parfois diminution du volume pulmonaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span> (patients distincts) — <span class=\"kw-radio\">syndromes interstitiels</span> : opacités <span class=\"kw-radio\">bilatérales, diffuses, non systématisées, réticulaires</span> (fines opacités linéaires) et/ou <span class=\"kw-radio\">micronodulaires</span> ; volume pulmonaire parfois diminué si <span class=\"kw-clinique\">évolution</span> fibrosante. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/tdm-syndrome-interstitiel.png\" alt=\"TDM thoraciques en coupes axiales, fenêtre parenchymateuse, de patients distincts montrant un verre dépoli n'effaçant pas les vaisseaux, des réticulations sous-pleurales et des images kystiques sous-pleurales multicouches en rayon de miel signant la fibrose\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM thoraciques</span>, coupes axiales, fenêtre parenchymateuse (patients distincts) — <span class=\"kw-radio\">syndromes interstitiels</span> (analyse plus précise et sensible que la <span class=\"kw-imagerie\">RXT</span>) : <span class=\"kw-radio\">verre dépoli</span> (densité n'effaçant pas <span class=\"kw-clinique\">les</span> vaisseaux), <span class=\"kw-radio\">réticulations</span> sous-pleurales (fines opacités linéaires), <span class=\"kw-radio\">rayon de miel</span> (images kystiques sous-pleurales multicouches, signe de fibrose). Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche diagnostique.</strong> Devant un syndrome interstitiel en <span class=\"kw-imagerie\">RXT</span>, l'enchaînement est : <span class=\"kw-radio\">TDM-HR sans injection</span> → bilan étiologique (clinique + biologie + LBA) → en cas de doute après bilan, <span class=\"kw-radio\">DMD</span> (discussion multidisciplinaire) puis ± <span class=\"kw-ttt\">biopsie</span> pulmonaire chirurgicale en dernier recours.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 210 — Pneumopathie interstitielle diffuse · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":4},{"id":"207-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une anomalie médiastinale","contenu":"<p>La pathologie des organes intra-médiastinaux, quelle que soit la cause, entraîne un ensemble de signes : le <span class=\"kw-def\">syndrome médiastinal</span>. <span class=\"kw-clinique\">Les</span> signes cliniques et radiographiques dépendent de la situation de l'organe atteint dans le médiastin et de la taille de la <span class=\"kw-clinique\">masse</span>. Cet objectif <span class=\"kw-alerte\">exclut la pathologie cardiovasculaire</span> (anévrysme aortique) et œsophagienne (hernie hiatale).</p>\n\n      <h5>Anatomie du médiastin — <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>9</span> l</span>oges</h5>\n      <p>Le médiastin est délimité par : en <strong>haut</strong> le défilé cervico-thoracique, en <strong>bas</strong> le diaphragme, en <strong>avant</strong> le sternum, en <strong>arrière</strong> <span class=\"kw-clinique\">les</span> vertèbres, <strong>latéralement</strong> les plèvres médiastines droite et gauche. Il est artificiellement séparé en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>9</span> l</span>oges par croisement de 3 étages et 3 compartiments.</p>\n\n      <table >\n        <thead><tr><th>Étage</th><th>Définition</th><th>Compartiment</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Supérieur</strong></td>\n            <td>Au-dessus de la portion horizontale de la crosse aortique</td>\n            <td><strong>Antérieur</strong></td>\n            <td>En avant de l'axe trachéal puis des vaisseaux et du péricarde</td>\n          </tr>\n          <tr>\n            <td><strong>Moyen</strong></td>\n            <td>Entre l'aorte et la carène</td>\n            <td><strong>Moyen</strong></td>\n            <td>Au niveau de l'axe trachéo-bronchique</td>\n          </tr>\n          <tr>\n            <td><strong>Inférieur</strong></td>\n            <td>En dessous de la carène</td>\n            <td><strong>Postérieur</strong></td>\n            <td>En arrière de l'axe trachéo-bronchique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-def\">Diagnostic positif</span> de la localisation médiastinale</h5>\n      <table >\n        <thead><tr><th>Modalité</th><th>Sémiologie</th><th>Limites</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">RXT</span></strong></td>\n            <td>\n              <strong>Limite externe :</strong> <span class=\"kw-imagerie\">nette, convexe vers le poumon</span><br>\n              <strong>Raccord :</strong> <span class=\"kw-imagerie\">en pente douce avec le médiastin</span><br>\n              <strong>Limite interne :</strong> non visible, fondue dans <span class=\"kw-clinique\">les</span> éléments médiastinaux<br>\n              <strong>Tonalité :</strong> hydrique comme le reste du médiastin<br>\n              <strong>Signe localisateur majeur :</strong> <span class=\"kw-imagerie\">signe de la silhouette</span> (<span class=\"kw-clinique\">masse</span> antérieure efface les bords antérieurs, et inversement)\n            </td>\n            <td><span class=\"kw-def\">Diagnostic différentiel</span> difficile avec opacités pariétales (raccord obtus) ou opacités parenchymateuses bordant le médiastin (raccord aigu)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> thoracique</strong> (examen <span class=\"kw-alerte\">essentiel</span> au diagnostic)</td>\n            <td>\n              <strong>Analyse :</strong> fenêtres permettant la détermination des densités <span class=\"kw-imagerie\">tissulaires</span>, <span class=\"kw-imagerie\">graisseuses</span> ou <span class=\"kw-imagerie\">liquidiennes</span><br>\n              <strong>Injection de PDC :</strong> identifie <span class=\"kw-clinique\">les</span> structures vasculaires normales, les distingue d'une structure tissulaire, apprécie la perméabilité vasculaire et exclut une pathologie vasculaire (anévrysme)\n            </td>\n            <td>Affirme la situation médiastinale de l'opacité ✅</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-mediastin-normal.png\" alt=\"Radiographie de thorax de face annotée et schéma anatomique des contours et lignes médiastinaux normaux : veine cave supérieure, tronc veineux brachio-céphalique droit, atrium droit, veine cave inférieure et ligne para-aortique à droite ; artère sous-clavière gauche, bouton aortique, artère pulmonaire et ventricule gauche à gauche\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie de thorax de face</span> et schéma — <span class=\"kw-radio\">contours et lignes médiastinaux normaux</span> : à droite, <span class=\"kw-radio\">VCS</span>, tronc veineux brachio-céphalique droit, atrium droit, <span class=\"kw-radio\">VCI</span>, ligne para-aortique ; à gauche, artère sous-clavière gauche, <span class=\"kw-radio\">bouton aortique</span>, artère pulmonaire, ventricule gauche. Connaître ces repères est le préalable à la détection d'une anomalie. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-masses-mediastinales.png\" alt=\"Deux radiographies de thorax de face de patients distincts montrant des masses médiastinales déformant les contours médiastinaux normaux (flèches), un lymphome à gauche et un thymome à droite\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span> (deux patients distincts) — <span class=\"kw-def\">masses médiastinales</span> (lymphome à gauche, thymome à droite). En faveur d'une localisation médiastinale : <span class=\"kw-radio\">limite externe nette avec le poumon</span>, <span class=\"kw-radio\">limite interne non visible</span> noyée dans l'opacité médiastinale ; ici <span class=\"kw-radio\">déformation des contours médiastinaux normaux</span> (flèches). Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <h5><span class=\"kw-def\">Diagnostic étiologique</span> — démarche par compartiment</h5>\n      <table >\n        <thead><tr><th>Compartiment</th><th>Démarche diagnostique</th><th>Pièges</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Médiastin antérieur</strong></td>\n            <td>\n              <strong>1) Dosages :</strong> <span class=\"kw-bio\">α-fœtoprotéine</span> + <span class=\"kw-bio\">HCG</span> (peut suffire au diagnostic d'une tumeur germinale)<br>\n              <strong>2) Preuve histologique :</strong> <span class=\"kw-ttt\">ponction</span> transpariétale à l'aiguille ; courte médiastinotomie antérieure (2ème EIC antérieur) ; chirurgie à visée diagnostique ET d'exérèse (si complète et peu mutilante = tumeur parfaitement limitée au <span class=\"kw-imagerie\">scanner</span>)\n            </td>\n            <td>\n              <strong>Règle :</strong> <span class=\"kw-alerte\">tester HCG et AFP AVANT de faire une biopsie</span><br>\n              <strong>Marqueurs sériques :</strong> peuvent se passer du diagnostic histologique s'ils sont élevés (valeur diagnostique)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médiastin moyen</strong></td>\n            <td>\n              <strong>1) Médiastinoscopie :</strong> test de référence pour <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">adénopathies</span> médiastinales (Se et Sp ≈ <span class=\"kw-chiffre\">100 %</span>) — limité aux adénopathies axiales (autour de la trachée) et de topographie haute (pas plus bas que la région précarinaire)<br>\n              <strong>2) <span class=\"kw-ttt\">Ponction</span> transbronchique à l'aiguille per-endoscopique échoguidée (<span class=\"kw-ttt\">EBUS</span>) :</strong> tend à remplacer la médiastinoscopie en <span class=\"kw-chiffre\">1ère intention</span>\n            </td>\n            <td>\n              <strong>Piège lymphome :</strong> <span class=\"kw-alerte\">si lymphome suspecté, la ponction à l'aiguille ne donne PAS assez de tissu</span> — la médiastinoscopie reste la règle (pour pouvoir typer le lymphome)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médiastin postérieur</strong></td>\n            <td>\n              <strong>Privilégier :</strong> <span class=\"kw-ttt\">ponction</span> transpariétale à l'aiguille ; ponction trans-œsophagienne à l'aiguille per-endoscopique échoguidée (<span class=\"kw-ttt\">EUS</span>)<br>\n              <strong><span class=\"kw-ttt\">Chirurgie</span> diagnostique + exérèse :</strong> envisageable seulement si <span class=\"kw-ttt\">exérèse</span> complète et peu mutilante (tumeur parfaitement limitée à l'imagerie)\n            </td>\n            <td>Tumeurs neurogènes : <span class=\"kw-clinique\">souvent bénignes chez l'adulte</span>, <span class=\"kw-alerte\">souvent malignes chez l'enfant</span> ; <span class=\"kw-imagerie\">IRM essentielle</span> pour reconnaître <span class=\"kw-clinique\">les</span> lésions infiltrantes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Cas particuliers</h5>\n      <table >\n        <thead><tr><th>Type</th><th>Cas typiques</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cas simples</strong> — aspect <span class=\"kw-imagerie\">TDM</span> typique de <span class=\"kw-clinique\">lésion</span> bénigne</td>\n            <td>\n              Goitre plongeant ; kystes bronchogéniques ; kystes pleuro-péricardiques ; tumeur thymique bien limitée et résécable d'emblée ; tumeurs neurogènes de l'adulte\n            </td>\n            <td><span class=\"kw-alerte\">Preuve histologique NON nécessaire</span> pour la décision</td>\n          </tr>\n          <tr>\n            <td><strong>Cas moins simples</strong> — <span class=\"kw-imagerie\">TDM</span> oriente vers une tumeur potentiellement maligne</td>\n            <td>\n              Lésions thymiques mal limitées ; tératomes / tumeurs germinales ; <span class=\"kw-clinique\">adénopathies</span> ; tumeurs neurogènes de l'enfant ; tumeurs mal limitées\n            </td>\n            <td><span class=\"kw-alerte\">Preuve histologique nécessaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Cas difficiles — <span class=\"kw-alerte\">urgence</span> vitale</strong> (compression médiastinale aiguë par <span class=\"kw-clinique\">masse</span> volumineuse chez homme jeune)</td>\n            <td>\n              Suspicion de tumeur germinale non séminomateuse (<span class=\"kw-clinique\">TGNS</span>)\n            </td>\n            <td>\n              <strong>1) Diagnostic de TGNS</strong> peut être porté sur la <span class=\"kw-alerte\">seule élévation franche d'α-fœtoprotéine ou de HCG</span><br>\n              <strong>2) Si négatif</strong> → <span class=\"kw-ttt\">ponction</span> transpariétale ou médiastinoscopie (-tomie)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 309 — Tumeurs du poumon · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":5},{"id":"207-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une atélectasie","contenu":"<p>L'<span class=\"kw-def\">atélectasie</span> est un <span class=\"kw-imagerie\">collapsus pulmonaire</span> par défaut de ventilation alvéolaire — le plus souvent par obstruction bronchique. C'est un syndrome <span class=\"kw-imagerie\">rétractile</span> (≠ syndrome alvéolaire non rétractile), particulièrement important à reconnaître car il fait évoquer en <span class=\"kw-chiffre\">première intention</span> un <span class=\"kw-alerte\">cancer bronchique proximal</span> chez le fumeur.</p>\n\n      <h5>Sémiologie radiographique — signes directs et indirects</h5>\n      <table >\n        <thead><tr><th>Type de signe</th><th>Sémiologie</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Opacité directe</strong></td>\n            <td><span class=\"kw-imagerie\">Opacité dense, homogène, rétractile</span> ; aspect triangulaire ou en bande selon le territoire collabé</td>\n            <td>Collapsus du parenchyme par résorption gazeuse alvéolaire</td>\n          </tr>\n          <tr>\n            <td><strong>Déviation des structures</strong></td>\n            <td>\n              <strong>Médiastin :</strong> <span class=\"kw-imagerie\">attiré vers l'opacité</span><br>\n              <strong>Hile :</strong> <span class=\"kw-imagerie\">ascensionné</span> homolatéral en cas d'atélectasie lobaire supérieure<br>\n              <strong>Scissures :</strong> <span class=\"kw-imagerie\">attirées vers le foyer</span>\n            </td>\n            <td>Signe pathognomonique du caractère rétractile (≠ comblement alvéolaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Ascension de la coupole</strong></td>\n            <td><span class=\"kw-imagerie\">Coupole diaphragmatique homolatérale élevée</span></td>\n            <td>Hypoventilation du poumon collabé</td>\n          </tr>\n          <tr>\n            <td><strong>Rétraction intercostale</strong></td>\n            <td><span class=\"kw-imagerie\">Pincement des espaces intercostaux</span> en regard</td>\n            <td>Diminution du volume pulmonaire homolatéral</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-imagerie\">TDM</span> — caractérisation de la cause</h5>\n      <p>La <span class=\"kw-ttt\">TDM thoracique injectée</span> est l'examen clé pour :</p>\n      <ul>\n        <li><strong>Confirmer le diagnostic</strong> d'atélectasie (collapsus du parenchyme, bronches non perméables, prise de contraste préservée des vaisseaux)</li>\n        <li><strong>Identifier la cause obstructive endo-bronchique :</strong> tumeur (<span class=\"kw-alerte\">cancer bronchique proximal +++</span> chez fumeur <span class=\"kw-chiffre\">≥ 50 ans</span>) ; corps étranger (enfant) ; bouchon muqueux ; sténose post-radique ou post-tuberculeuse</li>\n        <li><strong>Identifier la cause extrinsèque :</strong> compression par <span class=\"kw-clinique\">adénopathies</span>, masse médiastinale, anévrysme</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-atelectasie.png\" alt=\"Deux radiographies de thorax de face de patients distincts : à gauche atélectasie du lobe supérieur droit avec opacité homogène bien limitée sans bronchogramme, déplacement de la petite scissure vers le haut et déviation de la trachée ; à droite atélectasie du poumon gauche avec opacité homogène de l'hémithorax gauche sans bronchogramme et déviation de la trachée vers la gauche\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span> (deux patients distincts) — <span class=\"kw-def\">atélectasies</span>. <strong>À gauche :</strong> atélectasie du <span class=\"kw-radio\">lobe supérieur droit</span> — opacité homogène bien limitée <span class=\"kw-radio\">sans bronchogramme aérique</span>, <span class=\"kw-radio\">déplacement de la petite scissure vers le haut</span>, déviation de la trachée. <strong>À droite :</strong> atélectasie du <span class=\"kw-radio\">poumon gauche</span> — opacité homogène de l'hémithorax gauche sans bronchogramme, <span class=\"kw-radio\">déviation de la trachée vers la gauche</span> (signes rétractiles ≠ syndrome alvéolaire). Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeau rouge</span> — atélectasie chez l'adulte fumeur.</strong> <span class=\"kw-alerte\">Toute atélectasie chez un fumeur ≥ 50 ans doit faire évoquer un cancer bronchique proximal jusqu'à preuve du contraire</span> et déclencher une <span class=\"kw-radio\">endoscopie bronchique</span> en <span class=\"kw-alerte\">urgence</span> pour visualiser et biopsier la <span class=\"kw-clinique\">lésion</span> obstructive.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 209 — BPCO</em></p>","frequence":0},{"id":"207-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de prescription d’une radiographie thoracique en urgence","contenu":"<p>La <span class=\"kw-def\">radiographie thoracique (RXT)</span> reste l'examen d'imagerie de <span class=\"kw-imagerie\">première intention en urgence</span> devant la majorité des symptômes thoraciques. Sa rapidité, son accessibilité, sa faible <span class=\"kw-clinique\">irradiation</span> et son rendement diagnostique élevé en font un outil incontournable du raisonnement clinique en service d'<span class=\"kw-alerte\">urgence</span>. Objectif <span class=\"kw-chiffre\">Rang A</span> — fondamentaux à maîtriser.</p>\n\n      <h5>Indications cliniques</h5>\n      <table >\n        <thead><tr><th>Tableau clinique</th><th>Hypothèses recherchées</th><th>Signes radiographiques attendus</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Détresse</span> respiratoire aiguë</strong></td>\n            <td><span class=\"kw-alerte\">OAP</span>, pneumonie, PNO compressif, <span class=\"kw-alerte\">EP massive</span>, <span class=\"kw-alerte\">SDRA</span></td>\n            <td><span class=\"kw-imagerie\">Œdème péri-hilaire</span> ; <span class=\"kw-imagerie\">condensation</span> ; <span class=\"kw-imagerie\">ligne pleurale décollée</span> ; surcharge unilatérale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Douleur thoracique</span></strong></td>\n            <td>PNO, pneumonie, péricardite, EP, <span class=\"kw-alerte\"><span class=\"kw-etio\">dissection</span> aortique</span></td>\n            <td><span class=\"kw-imagerie\">Hyperclarté apicale</span> ; <span class=\"kw-imagerie\">opacité alvéolaire</span> ; <span class=\"kw-imagerie\">élargissement médiastinal</span></td>\n          </tr>\n          <tr>\n            <td><strong>Traumatisme thoracique</strong></td>\n            <td>Fracture costale, PNO, hémothorax, contusion pulmonaire, volet costal</td>\n            <td>Cf obj-1 ; <span class=\"kw-imagerie\">opacité pleurale déclive</span> ; <span class=\"kw-imagerie\">épaississement pariétal</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Fièvre</span> + signes respiratoires</strong></td>\n            <td>Pneumonie infectieuse, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-clinique\">abcès</span></td>\n            <td><span class=\"kw-imagerie\">Foyer alvéolaire systématisé</span> ; <span class=\"kw-imagerie\">image cavitaire</span></td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion d'<span class=\"kw-alerte\">embolie pulmonaire</span></strong></td>\n            <td>EP avec ou sans <span class=\"kw-clinique\">infarctus</span> pulmonaire</td>\n            <td><span class=\"kw-imagerie\">RXT</span> souvent <span class=\"kw-alerte\">normale</span> ; parfois atélectasie en bande, ascension de la coupole, opacité périphérique triangulaire (signe de Hampton)</td>\n          </tr>\n          <tr>\n            <td><strong>Post-procédure</strong></td>\n            <td>Vérification de position de sonde d'<span class=\"kw-ttt\">intubation</span>, KT central, drain thoracique, sonde nasogastrique ; recherche de complication immédiate (PNO <span class=\"kw-etio\">iatrogène</span>)</td>\n            <td>Position des dispositifs ; <span class=\"kw-imagerie\">PNO post-pose KT central</span> à éliminer</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Modalités pratiques de prescription</h5>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Choix de référence</th><th>Pièges / dérogations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Incidences</strong></td>\n            <td>\n              <strong>Face postéro-antérieure (PA) :</strong> <span class=\"kw-def\">incidence</span> de référence en <span class=\"kw-chiffre\">première intention</span><br>\n              <strong>Profil :</strong> ajouté si suspicion pleurale, médiastinale, scissurale ou rétrocardiaque\n            </td>\n            <td><span class=\"kw-alerte\">Patient instable</span> non transportable au plateau technique → cliché de face <span class=\"kw-imagerie\">antéro-postérieur (AP) couché au lit</span> ; <span class=\"kw-alerte\">moins informatif</span> (élargissement médiastinal artéfactuel, scapulae superposées)</td>\n          </tr>\n          <tr>\n            <td><strong>Position</strong></td>\n            <td><span class=\"kw-imagerie\">Debout</span>, en inspiration profonde, dos contre la <span class=\"kw-clinique\">plaque</span></td>\n            <td>Position couchée modifie la sémiologie pleurale (épanchement liquidien diffus au lieu de cul-de-sac) et fausse l'évaluation médiastinale</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Critères de</span> qualité</strong></td>\n            <td>\n              <strong>Inspiration :</strong> 6 arcs antérieurs ou 9-10 arcs postérieurs visibles<br>\n              <strong>Centrage :</strong> apophyses épineuses centrées entre <span class=\"kw-clinique\">les</span> clavicules<br>\n              <strong>Pénétration :</strong> visualisation des disques intervertébraux à travers le médiastin\n            </td>\n            <td>Cliché insuffisamment pénétré → faux diagnostic d'opacité parenchymateuse ; cliché en expiration → fausse cardiomégalie</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Limites à connaître.</strong> Une <span class=\"kw-alerte\">RXT normale n'élimine pas</span> un diagnostic urgent — particulièrement l'<span class=\"kw-clinique\">embolie pulmonaire</span> (<span class=\"kw-imagerie\">RXT</span> souvent normale), une <span class=\"kw-clinique\">pneumonie débutante</span> (latence radio-clinique de <span class=\"kw-chiffre\">24-48 h</span>), ou une <span class=\"kw-clinique\">dissection aortique</span> (élargissement médiastinal subtil). Le raisonnement clinique reste maître.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 206 — Epanchement pleural · 226 — Thrombose veineuse profonde - EP · 154 — Infection bronchopulmonaire communautaire</em></p>","frequence":0},{"id":"207-10","rang":"B","rubrique":"Diagnostic positif","titre":"Identifier une image thymique normale sur une radiographie thoracique de face chez un nourrisson","contenu":"<p>Le <span class=\"kw-def\">thymus</span> est physiologiquement <span class=\"kw-imagerie\">assez volumineux chez le nourrisson</span>, avec des présentations radiologiques très variées. C'est un piège classique d'imagerie pédiatrique : un thymus normal peut être confondu avec une <span class=\"kw-clinique\">masse</span> médiastinale.</p>\n\n      <h5><span class=\"kw-clinique\">Évolution</span> radiologique du thymus avec l'âge</h5>\n      <table >\n        <thead><tr><th>Âge</th><th>Présentation radiologique</th><th>Implications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Nourrisson</strong></td>\n            <td>Thymus <span class=\"kw-imagerie\">volumineux</span>, présentations <span class=\"kw-imagerie\">très variées</span> en <span class=\"kw-imagerie\">RXT</span> de face</td>\n            <td>\n              <strong>Aspect typique :</strong> opacité médiastinale antéro-supérieure ; bords latéraux convexes ; <span class=\"kw-imagerie\">signe de la voile</span> ou <span class=\"kw-imagerie\">signe de la vague</span> possibles\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">2–3 ans</span></strong></td>\n            <td>Thymus <span class=\"kw-imagerie\">disparaît sur le plan radiologique</span> le plus souvent</td>\n            <td>Seuil clé à retenir : passé<span class=\"kw-chiffre\"> 3 ans</span>, une <span class=\"kw-clinique\">masse</span> médiastinale antérieure doit faire évoquer une autre étiologie</td>\n          </tr>\n          <tr>\n            <td><strong>Grand enfant</strong></td>\n            <td>Résidu thymique possible dans la <span class=\"kw-imagerie\">fenêtre aorto-pulmonaire</span></td>\n            <td>Peut faire évoquer à tort une <span class=\"kw-clinique\">masse</span> médiastinale — connaissance du piège</td>\n          </tr>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td>Thymus subit une <span class=\"kw-imagerie\">involution adipeuse</span> ; disparaît au profit d'un <span class=\"kw-imagerie\">reliquat graisseux rétrosternal</span></td>\n            <td>\n              <strong><span class=\"kw-alerte\">Drapeau rouge</span> :</strong> <span class=\"kw-alerte\">une augmentation de taille de la glande thymique est considérée comme pathologique après l'âge de &gt; 40 ans</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-thymus-normal-nourrisson.png\" alt=\"Deux radiographies de thorax de face de deux nourrissons distincts âgés de 6 mois montrant un débord thymique bilatéral normal chez l'un et un débord thymique droit normal chez l'autre\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span> (2 enfants distincts âgés de <span class=\"kw-chiffre\">6 mois</span>) — <span class=\"kw-radio\">images thymiques normales</span> : <span class=\"kw-radio\">débord thymique bilatéral normal</span> (gauche) et <span class=\"kw-radio\">débord thymique droit normal</span> (droite). À ne pas confondre avec une <span class=\"kw-clinique\">masse</span> médiastinale : le thymus disparaît radiologiquement vers <span class=\"kw-chiffre\">2-3 ans</span>. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique en imagerie pédiatrique.</strong> Sur une <span class=\"kw-imagerie\">RXT</span> de nourrisson, un <span class=\"kw-imagerie\">élargissement médiastinal antéro-supérieur</span> peut être <strong>physiologique</strong> et correspondre simplement au thymus. Ne pas surinterpréter en <span class=\"kw-clinique\">masse</span> médiastinale — la disparition radiologique normale survient entre <span class=\"kw-chiffre\">2 et 3 ans</span>.\n      </div>","frequence":2},{"id":"207-11","rang":"B","rubrique":"Diagnostic positif","titre":"Identifier une image médiastinale anormale chez le nourrisson et l’enfant et prescrire une tomodensitométrie thoracique","contenu":"<p>Identifier une <span class=\"kw-def\">image médiastinale anormale</span> chez le nourrisson et l'enfant repose sur la connaissance des présentations physiologiques selon l'âge (cf obj-9 pour le thymus) puis sur la reconnaissance des signes radiologiques d'opacité médiastinale anormale, ce qui doit conduire à prescrire une <span class=\"kw-ttt\">tomodensitométrie thoracique</span>.</p>\n\n      <h5>Critères radiologiques d'opacité médiastinale anormale</h5>\n      <table >\n        <thead><tr><th>Critère</th><th>Sémiologie attendue</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Limite externe</strong></td><td><span class=\"kw-imagerie\">Nette, convexe vers le poumon</span></td></tr>\n          <tr><td><strong>Raccord</strong></td><td><span class=\"kw-imagerie\">Pente douce avec le médiastin</span> (≠ raccord aigu d'une opacité parenchymateuse périphérique)</td></tr>\n          <tr><td><strong>Limite interne</strong></td><td><span class=\"kw-imagerie\">Non visible</span> — fondue dans <span class=\"kw-clinique\">les</span> éléments médiastinaux</td></tr>\n          <tr><td><strong>Tonalité</strong></td><td><span class=\"kw-imagerie\">Hydrique</span>, identique au reste du médiastin</td></tr>\n          <tr><td><strong>Signe de la silhouette</strong></td><td>Valeur localisatrice majeure : déformation ou déplacement d'une ligne médiastinale ; une <span class=\"kw-clinique\">masse</span> antérieure efface <span class=\"kw-clinique\">les</span> bords antérieurs et inversement</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Indications du <span class=\"kw-imagerie\">TDM</span> thoracique chez l'enfant</h5>\n      <p>La <span class=\"kw-ttt\">TDM thoracique injectée</span> est l'examen de référence dès lors qu'une anomalie médiastinale est suspectée sur la <span class=\"kw-imagerie\">RXT</span> chez l'enfant. Elle permet :</p>\n      <ul>\n        <li>De confirmer la situation médiastinale (<span class=\"kw-bio\">vs</span> intra-parenchymateuse ou pariétale)</li>\n        <li>D'analyser <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">densités tissulaires, graisseuses ou liquidiennes</span></li>\n        <li>D'identifier <span class=\"kw-clinique\">les</span> <span class=\"kw-imagerie\">structures vasculaires</span> grâce à l'injection de produit de contraste</li>\n        <li>D'exclure une <span class=\"kw-imagerie\">pathologie vasculaire</span> (anévrysme, malformation, anomalie des arcs)</li>\n        <li>De localiser précisément la <span class=\"kw-clinique\">masse</span> dans l'une des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>9</span> l</span>oges (cf obj-6) — orientation étiologique majeure (cf obj-11)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Particularité pédiatrique.</strong> Chez l'enfant, <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">tumeurs neurogènes</span> du médiastin postérieur (neuroblastomes, neurofibromes) sont <span class=\"kw-alerte\">souvent malignes</span> — l'<span class=\"kw-imagerie\">IRM</span> complète volontiers la <span class=\"kw-imagerie\">TDM</span> pour rechercher des extensions infiltrantes (canal rachidien, foramen).\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/207/rp-masse-mediastinale-enfant.png\" alt=\"Deux radiographies de thorax de face chez l'enfant : chez un enfant de 8 ans une masse médiastinale correspondant à un neuroblastome ; chez un enfant de 12 ans une masse médiastinale correspondant à un lymphome avec sténose trachéale, élargissement médiastinal et perte de visualisation de la ligne para-aortique\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span> chez l'enfant — <span class=\"kw-def\">masses médiastinales anormales</span>. <strong>Enfant de <span class=\"kw-chiffre\">8 ans</span> :</strong> <span class=\"kw-clinique\">masse</span> médiastinale (<span class=\"kw-alerte\">neuroblastome</span>). <strong>Enfant de <span class=\"kw-chiffre\">12 ans</span> :</strong> masse médiastinale (<span class=\"kw-alerte\">lymphome</span>) — <span class=\"kw-radio\">sténose trachéale</span>, <span class=\"kw-radio\">déformations des contours médiastinaux droits</span>, <span class=\"kw-radio\">élargissement médiastinal supérieur, moyen et inférieur</span>, <span class=\"kw-radio\">perte de visualisation de la ligne para-aortique</span> → prescrire une <span class=\"kw-imagerie\">TDM</span> thoracique. Source : banque imagerie « Imagerie à connaître » (item 207).</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":1},{"id":"207-12","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales hypothèses diagnostiques devant une anomalie médiastinale selon la topographie chez l’enfant","contenu":"<p>L'orientation étiologique d'une anomalie médiastinale chez l'enfant suit la <strong>topographie de la <span class=\"kw-clinique\">masse</span></strong> dans l'une des <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>9</span> l</span>oges (cf obj-6 pour l'anatomie). À chaque compartiment ses étiologies spécifiques.</p>\n\n      <h5>Médiastin antérieur</h5>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Étage</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Goitres plongeants</strong></td>\n            <td>Supérieur</td>\n            <td>Tumeur en général bénigne, développée à partir d'un lobe thyroïdien et plongeant à travers le défilé cervico-thoracique</td>\n          </tr>\n          <tr>\n            <td><strong>Lésions parathyroïdiennes</strong></td>\n            <td>Supérieur</td>\n            <td>Adénomes parathyroïdiens ectopiques</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeurs thymiques</strong> (TET)</td>\n            <td>Moyen</td>\n            <td>\n              <strong>Kystes :</strong> kystes et tumeurs bénignes thymiques<br>\n              <strong>Tumeurs épithéliales :</strong> essentiel des tumeurs du médiastin antérieur ; <span class=\"kw-clinique\">carcinomes thymiques</span> (potentiel invasif et métastatique maximal) ; thymomes type A (potentiel minime)<br>\n              <strong>Découverte possible :</strong> par une <span class=\"kw-clinique\">myasthénie</span> ⭐ liée à la production par la tumeur d'AC anti-récepteurs de l'acétylcholine<br>\n              <strong>Lymphomes thymiques :</strong> adulte jeune, prédominance féminine ; Hodgkin, lymphome B à grandes cellules, lymphome T lymphoblastique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Tumeurs germinales</strong></td>\n            <td>Moyen</td>\n            <td>\n              <strong>Origine :</strong> transformation de cellules primitives (futurs ovules/spermatozoïdes) dont la migration s'est arrêtée au médiastin pendant la vie embryonnaire<br>\n              <strong>Tératomes (<span class=\"kw-chiffre\">60–70 %</span>) :</strong> tumeurs germinales bénignes<br>\n              <strong>TGS :</strong> séminome (tumeur maligne, homme jeune ~<span class=\"kw-chiffre\">39 ans</span>)<br>\n              <strong>TGNS :</strong> <span class=\"kw-clinique\">carcinome</span> embryonnaire (<span class=\"kw-bio\">AFP</span>) ; choriocarcinome (<span class=\"kw-bio\">HCG</span>) ; tumeur du sac vitellin (<span class=\"kw-bio\">AFP</span>) ; tératome<br>\n              <strong>Règle :</strong> <span class=\"kw-alerte\">tester HCG et AFP AVANT toute biopsie</span> — marqueurs sériques à valeur diagnostique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Kystes pleuro-péricardiques</strong></td>\n            <td>Inférieur</td>\n            <td>Tumeurs liquidiennes situées dans l'<span class=\"kw-imagerie\">angle cardiophrénique</span> ; <span class=\"kw-clinique\">asymptomatiques</span> le plus souvent</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Médiastin moyen</h5>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Sous-catégorie</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td rowspan=\"3\"><strong><span class=\"kw-clinique\">Adénopathies</span> médiastinales</strong> (essentiel du médiastin moyen)</td>\n            <td><strong>Tumorales</strong></td>\n            <td>Cancers bronchopulmonaires ; lymphomes ; <span class=\"kw-clinique\">LLC</span> ; métastases ganglionnaires de cancers extra-thoraciques</td>\n          </tr>\n          <tr>\n            <td><strong>Non tumorales</strong></td>\n            <td><span class=\"kw-clinique\">Sarcoïdose</span> ; <span class=\"kw-etio\">tuberculose</span> ; silicose ; infections parenchymateuses chroniques ; histoplasmose (Amérique du Nord)</td>\n          </tr>\n          <tr>\n            <td><strong>Diffuses, non spécifiques, taille modérée</strong></td>\n            <td><span class=\"kw-ci\">Insuffisance cardiaque</span> gauche</td>\n          </tr>\n          <tr>\n            <td><strong>Kystes bronchogéniques</strong></td>\n            <td>—</td>\n            <td>Masses régulières, arrondies, de <span class=\"kw-imagerie\">contenu liquidien</span> au <span class=\"kw-def\">contact</span> de l'arbre bronchique</td>\n          </tr>\n          <tr>\n            <td><strong>Paragangliomes</strong></td>\n            <td>—</td>\n            <td>Tumeurs rares, neuroendocrines</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Médiastin postérieur</h5>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">tumeurs neurogènes</span> dominent largement (~1/3 des tumeurs du médiastin) — exemples : schwannomes, neuroblastomes, neurofibromes, paragangliomes.</p>\n      <ul>\n        <li><strong>Adulte :</strong> <span class=\"kw-clinique\">souvent bénignes</span></li>\n        <li><strong>Enfant :</strong> <span class=\"kw-alerte\">souvent malignes</span> — particularité pédiatrique majeure à connaître</li>\n        <li><strong>Imagerie :</strong> <span class=\"kw-imagerie\">IRM essentielle</span> pour le bilan lésionnel — reconnaître <span class=\"kw-clinique\">les</span> lésions infiltrantes (canal rachidien, foramen)</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> pédiatrique.</strong> Toute <span class=\"kw-clinique\">masse</span> du médiastin postérieur chez l'enfant doit faire évoquer en priorité un <span class=\"kw-alerte\">neuroblastome malin</span> et déclencher la séquence : <span class=\"kw-imagerie\">TDM</span> (urgent) → <span class=\"kw-imagerie\">IRM</span> rachidienne (extension intra-canalaire) → discussion en <span class=\"kw-def\">RCP</span> pédiatrique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence vitale</span> rare = <span class=\"kw-etio\">compression médiastinale aiguë</span> par une <span class=\"kw-clinique\">masse</span> volumineuse, chez un <span class=\"kw-clinique\">homme jeune</span> suspect de <span class=\"kw-etio\">TGNS</span> (tumeur germinale non séminomateuse).<br><strong>1er geste :</strong> doser <span class=\"kw-bio\">α-fœtoprotéine (AFP)</span> + <span class=\"kw-bio\">β-HCG</span> AVANT toute <span class=\"kw-ttt\">biopsie</span>.<br><strong>Règle :</strong> le diagnostic de <span class=\"kw-etio\">TGNS</span> peut être porté sur la seule élévation franche de l'<span class=\"kw-bio\">AFP</span> ou de l'HCG ; si négatif → <span class=\"kw-ttt\">ponction transpariétale</span> ou <span class=\"kw-ttt\">médiastinoscopie</span>.<br><strong>Imagerie en <span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-imagerie\">radiographie thoracique</span> = examen de débrouillage (rang A) ; <span class=\"kw-alerte\">détresse</span> respiratoire / <span class=\"kw-alerte\">stridor</span> imposent des explorations radiologiques.</p>","redflags":"<p><strong>Syndrome médiastinal</strong> = ensemble de signes de compression des organes intramédiastinaux ; oriente vers une <span class=\"kw-clinique\">masse</span> volumineuse ou maligne.</p><ul><li><span class=\"kw-clinique\">Syndrome cave supérieur</span> (le plus fréquent) — compression veineuse</li><li><span class=\"kw-clinique\">Syndrome de Claude Bernard-Horner</span> : myosis, ptosis, énophtalmie</li><li><span class=\"kw-clinique\">Paralysie récurrentielle</span> (dysphonie) ; <span class=\"kw-clinique\">paralysie phrénique</span> (ascension d'une coupole diaphragmatique)</li><li><span class=\"kw-alerte\">Compression médullaire</span> par tumeur « en sablier » (médiastin postérieur)</li><li><span class=\"kw-clinique\">Compression œsophagienne</span> : <span class=\"kw-clinique\">dysphagie</span>, pyrosis, hypersialorrhée</li><li><span class=\"kw-alerte\">Stridor, dyspnée aux 2 temps, détresse respiratoire</span> (enfant)</li><li><span class=\"kw-clinique\">Toux persistante</span> résistante aux traitements symptomatiques (bronchodilatateurs, <span class=\"kw-ttt\">corticoïdes</span>)</li><li>Signes <span class=\"kw-imagerie\">RXT</span> indirects de malignité : <span class=\"kw-radio\">atélectasie</span>, <span class=\"kw-radio\">épanchement pleural</span>, <span class=\"kw-radio\">adénopathies hilaires/médiastinales</span>, <span class=\"kw-radio\">lyse costale ou vertébrale</span></li><li>Élargissement du médiastin <span class=\"kw-clinique\">antéro-supérieur chez l'adolescent</span> → évoquer un <span class=\"kw-etio\">lymphome</span> (Hodgkin ou LMNH)</li></ul>","principes":"<p>Démarche diagnostique : <span class=\"kw-imagerie\">RXT</span> (face + profil) → <span class=\"kw-imagerie\">TDM</span> thoracique → caractérisation → prélèvement adapté à la localisation.</p><p><strong><span class=\"kw-def\">Diagnostic positif</span> & topographie</strong></p><p>La <span class=\"kw-imagerie\">TDM</span> affirme la localisation médiastinale de l'opacité.</p><ul><li><span class=\"kw-imagerie\">RXT face + profil</span> = débrouillage ; opacité médiastinale = limite externe nette convexe vers le poumon, raccord en pente douce, tonalité hydrique, limite interne non visible.</li><li><span class=\"kw-radio\">Signe de la silhouette</span> = valeur localisatrice (une <span class=\"kw-clinique\">masse</span> antérieure efface <span class=\"kw-clinique\">les</span> bords du médiastin).</li><li><span class=\"kw-imagerie\">TDM thoracique injectée</span> = examen essentiel : affirme la situation médiastinale, détermine <span class=\"kw-clinique\">les</span> densités (tissulaire / graisseuse / liquidienne), distingue une pathologie vasculaire (anévrysme).</li><li>Une <span class=\"kw-imagerie\">RXT</span> normale n'élimine pas un cancer bronchique (rare, <span class=\"kw-chiffre\">&lt; 5%</span>).</li></ul><p><strong>Caractérisation du <span class=\"kw-clinique\">nodule</span> parenchymateux</strong></p><ul><li>Tailles (au <span class=\"kw-imagerie\">scanner</span>) : <span class=\"kw-def\">micronodule</span> <span class=\"kw-chiffre\">&lt; 3 mm</span> ; <span class=\"kw-def\">nodule</span> <span class=\"kw-chiffre\">3-30 mm</span> ; <span class=\"kw-def\">masse</span> <span class=\"kw-chiffre\">&gt; 3 cm</span>.</li><li>Densité : <span class=\"kw-radio\">solide</span>, <span class=\"kw-radio\">verre dépoli pur</span> ou mixte.</li><li>La <span class=\"kw-imagerie\">RX</span> n'a aucune place pour découvrir un micronodule/<span class=\"kw-clinique\">nodule</span>, ni dans le <span class=\"kw-def\">dépistage</span>.</li><li>Aucun argument morphologique n'est formel : seule l'<span class=\"kw-ttt\">histologie</span> donne la certitude.</li></ul><p><strong>Bilan <span class=\"kw-ttt\">biologique</span> avant prélèvement</strong></p><p><span class=\"kw-clinique\">Masse</span> du médiastin antérieur : doser <span class=\"kw-bio\">α-fœtoprotéine</span> + <span class=\"kw-bio\">β-HCG</span> de façon systématique, AVANT toute <span class=\"kw-ttt\">biopsie</span>.</p><ul><li><span class=\"kw-bio\">Fonction rénale</span> (pour l'injection de produit de contraste).</li><li><span class=\"kw-bio\">Bilan d'hémostase</span> : <span class=\"kw-bio\">NFS, TP, TCA</span> (pour autoriser <span class=\"kw-clinique\">les</span> biopsies).</li><li><span class=\"kw-bio\">Marqueurs sériques</span> NON recommandés en routine (aucune indication).</li></ul><p><strong>Choix de la technique de prélèvement (selon localisation)</strong></p><p>L'<span class=\"kw-bio\">histologie</span> donne le diagnostic de certitude — sauf TGNS avec marqueurs élevés.</p><ul><li><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-radio\">centrale</span> (1/3 péri-carène) : <span class=\"kw-ttt\">fibroscopie bronchique</span> (systématique si suspicion de cancer).</li><li><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-radio\">périphérique</span> (1/3 externe) : <span class=\"kw-ttt\">ponction transpariétale</span> à l'aiguille (sensibilité <span class=\"kw-chiffre\">~90%</span>) ou <span class=\"kw-ttt\">vidéo-thoracoscopie</span>.</li><li><span class=\"kw-clinique\">Adénopathies</span> au <span class=\"kw-def\">contact</span> de la trachée : <span class=\"kw-ttt\">écho-endoscopie (EBUS/EUS)</span>, <span class=\"kw-ttt\">médiastinoscopie</span>.</li><li><span class=\"kw-ci\">CI fibroscopie</span> : hypoxémie réfractaire à l'<span class=\"kw-ttt\">oxygénothérapie</span>, anomalies majeures de la coagulation.</li><li>Si <span class=\"kw-etio\">lymphome</span> suspecté : la <span class=\"kw-ttt\">ponction</span> à l'aiguille est insuffisante → <span class=\"kw-ttt\">médiastinoscopie</span> reste la règle.</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/pneumologie-cardiologie/opacites-masses-intrathoraciques","label":"Pedia-univ — Opacites masses intrathoraciques"},{"href":"https://radiopaedia.org/articles/thymus","label":"Radiopaedia : Thymus"},{"href":"https://radiopaedia.org/articles/teratoma-1","label":"Radiopaedia : Teratoma 1"},{"href":"https://radiopaedia.org/articles/mediastinal-lymph-node-enlargement","label":"Radiopaedia : Mediastinal lymph node enlargement"},{"href":"https://radiopaedia.org/articles/aspergilloma","label":"Radiopaedia : Aspergilloma"},{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_207_OPACITES_MASSES_2023.pdf","label":"Collège (CEP) — Item 207 opacites masses 2023"},{"href":"https://radiopaedia.org/articles/parathyroid-adenoma","label":"Radiopaedia : Parathyroid adenoma"},{"href":"https://radiopaedia.org/articles/thymic-epithelial-tumours","label":"Radiopaedia : Thymic epithelial tumours"},{"href":"https://radiopaedia.org/articles/germ-cell-tumours","label":"Radiopaedia : Germ cell tumours"},{"href":"https://radiopaedia.org/articles/pericardial-cyst","label":"Radiopaedia : Pericardial cyst"},{"href":"https://radiopaedia.org/articles/bronchogenic-cyst","label":"Radiopaedia : Bronchogenic cyst"},{"href":"https://radiopaedia.org/articles/mediastinal-paraganglioma-1","label":"Radiopaedia : Mediastinal paraganglioma 1"},{"href":"https://radiopaedia.org/articles/intrapulmonary-lymph-nodes-1","label":"Radiopaedia : Ganglion intra-pulmonaire"},{"href":"https://radiopaedia.org/articles/pulmonary-hamartoma-1","label":"Hamartochondrome"},{"href":"https://radiopaedia.org/articles/lung-abscess","label":"Abcès du poumon à pyogène"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Opacité / masse intra-thoracique sur RXT — TDM thoracique = examen clé (affirme la topographie)","detail":"<h4>CAT — Démarche diagnostique devant une opacité / <span class=\"kw-clinique\">masse</span> intra-thoracique — <span class=\"kw-imagerie\">RXT</span> → <span class=\"kw-imagerie\">TDM</span> (topographie) → technique de prélèvement adaptée à la localisation</h4>","branches":[{"to":"q-loc","label":"TDM précise la topographie","color":"blue"}]},{"id":"q-loc","kind":"decision","label":"Opacité parenchymateuse ou masse médiastinale ?","branches":[{"to":"q-parench","label":"Opacité intra-parenchymateuse","color":"blue"},{"to":"q-compart","label":"Masse médiastinale","color":"blue"}]},{"id":"q-parench","kind":"decision","label":"Localisation de la lésion dans le poumon ?","branches":[{"to":"t-fibro","label":"Lésion centrale (1/3 péri-carène)","color":"blue"},{"to":"t-transpariet","label":"Lésion périphérique (1/3 externe)","color":"blue"}]},{"id":"t-fibro","kind":"terminal","label":"Fibroscopie bronchique","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Fibroscopie bronchique</span> (<span class=\"kw-imagerie\">bronchoscopie</span> souple) en <span class=\"kw-chiffre\">1ère intention</span> pour <span class=\"kw-clinique\">les</span> lésions <span class=\"kw-radio\">centrales</span> (1/3 du thorax autour de la carène).</li><li>Systématique si suspicion de <span class=\"kw-etio\">cancer bronchique</span> : recherche de lésions radio-occultes même si la <span class=\"kw-clinique\">lésion</span> est périphérique (une <span class=\"kw-imagerie\">fibroscopie</span> normale n'élimine pas le diagnostic).</li><li>Biopsies bronchiques : minimum <span class=\"kw-chiffre\">3-5</span>, avec <span class=\"kw-ttt\">biopsie</span> de l'éperon sus-jacent et de la carène.</li></ul><h4><span class=\"kw-ci\">Contre-indications</span></h4><ul><li><span class=\"kw-ci\">Hypoxémie réfractaire</span> à une <span class=\"kw-ttt\">oxygénothérapie</span> adaptée.</li><li><span class=\"kw-ci\">Anomalies majeures de la coagulation</span>.</li></ul>"},{"id":"t-transpariet","kind":"terminal","label":"Ponction-biopsie transpariétale","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Ponction-biopsie transpariétale</span> à l'aiguille pour <span class=\"kw-clinique\">les</span> nodules et masses <span class=\"kw-radio\">périphériques</span>, sous guidage <span class=\"kw-imagerie\">TDM</span> (écho-guidée si <span class=\"kw-def\">contact</span> pariétal).</li><li>Alternative : <span class=\"kw-ttt\">vidéo-thoracoscopie</span> exploratrice.</li><li>Bonne rentabilité (sensibilité <span class=\"kw-chiffre\">~90%</span>) ; une négativité (<span class=\"kw-chiffre\">10-15%</span>) n'élimine pas le diagnostic.</li><li><span class=\"kw-clinique\">Lésion</span> intermédiaire (entre centre et périphérie) : <span class=\"kw-ttt\">fibroscopie</span> + <span class=\"kw-ttt\">ponction transpariétale</span> ± <span class=\"kw-ttt\">thoracotomie exploratrice</span>.</li></ul><h4>Complications</h4><ul><li><span class=\"kw-alerte\">Pneumothorax</span> (<span class=\"kw-chiffre\">~10%</span> des cas) ; <span class=\"kw-alerte\">hémoptysie</span> plus rare.</li><li>Évaluation spirométrique préalable utile (mauvaise tolérance possible si <span class=\"kw-ci\">insuffisance respiratoire</span>).</li></ul><h4>Renvoi</h4><ul><li>Item 309 (Tumeurs du poumon) — cancers bronchopulmonaires primitifs et métastases pulmonaires.</li></ul>"},{"id":"q-compart","kind":"decision","label":"Quel compartiment médiastinal ?","branches":[{"to":"q-marqueurs","label":"Médiastin antérieur","color":"blue"},{"to":"t-moyen","label":"Médiastin moyen","color":"blue"},{"to":"t-posterieur","label":"Médiastin postérieur","color":"blue"}]},{"id":"q-marqueurs","kind":"decision","label":"AFP / β-HCG élevés ? — Masse du médiastin antérieur","branches":[{"to":"t-tgns","label":"Élévation franche","color":"red"},{"to":"t-ant-biopsie","label":"Marqueurs normaux","color":"amber"}]},{"id":"t-tgns","kind":"terminal","label":"TGNS — diagnostic possible sans biopsie","color":"red","detail":"<h4>Conduite</h4><ul><li>Élévation franche de l'<span class=\"kw-bio\">α-fœtoprotéine</span> ou de l'<span class=\"kw-bio\">HCG</span> → le diagnostic de <span class=\"kw-etio\">TGNS</span> (tumeur germinale non séminomateuse) peut être porté SANS <span class=\"kw-ttt\">biopsie</span>.</li><li><span class=\"kw-alerte\">Urgence vitale</span> si <span class=\"kw-etio\">compression médiastinale aiguë</span> par une <span class=\"kw-clinique\">masse</span> volumineuse (homme jeune).</li></ul><h4>Règle</h4><ul><li>Toujours doser <span class=\"kw-bio\">AFP</span> + <span class=\"kw-bio\">β-HCG</span> AVANT toute <span class=\"kw-ttt\">biopsie</span> d'une <span class=\"kw-clinique\">masse</span> du médiastin antérieur.</li><li>Si marqueurs négatifs : <span class=\"kw-ttt\">ponction transpariétale</span> ou <span class=\"kw-ttt\">médiastinoscopie</span> / médiastinotomie.</li></ul><h4>Renvoi</h4><ul><li>Item 313 (Tumeurs du testicule) — marqueurs des tumeurs germinales.</li></ul>"},{"id":"t-ant-biopsie","kind":"terminal","label":"Médiastin antérieur — preuve histologique","color":"amber","detail":"<h4>Conduite</h4><ul><li>Marqueurs normaux → <span class=\"kw-ttt\">preuve histologique</span> nécessaire.</li><li><span class=\"kw-ttt\">Ponction transpariétale</span> à l'aiguille, ou courte <span class=\"kw-ttt\">médiastinotomie antérieure</span> (<span class=\"kw-chiffre\">2ᵉ EIC antérieur</span>).</li><li><span class=\"kw-ttt\">Chirurgie diagnostique + exérèse</span> d'emblée si tumeur limitée et résécable au <span class=\"kw-imagerie\">scanner</span> (ex. <span class=\"kw-etio\">thymome</span> bien limité).</li></ul><h4>Étiologies (médiastin antérieur)</h4><ul><li><span class=\"kw-etio\">Goitre plongeant</span>, <span class=\"kw-etio\">lésions parathyroïdiennes</span>, <span class=\"kw-etio\">tumeurs thymiques</span> (TET ± <span class=\"kw-clinique\">myasthénie</span> associée), <span class=\"kw-etio\">tumeurs germinales</span>, <span class=\"kw-etio\">kystes pleuro-péricardiques</span>.</li></ul>"},{"id":"t-moyen","kind":"terminal","label":"Médiastin moyen — adénopathies","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Ponction transbronchique à l'aiguille échoguidée (EBUS)</span> en <span class=\"kw-chiffre\">1ère intention</span>.</li><li><span class=\"kw-ttt\">Médiastinoscopie</span> = test de référence des <span class=\"kw-clinique\">adénopathies</span> axiales hautes (Se/Sp <span class=\"kw-chiffre\">~100%</span> ; performante seulement autour de la trachée, pas au-delà de la région précarinaire).</li></ul><h4>Piège lymphome</h4><ul><li>Si <span class=\"kw-etio\">lymphome</span> suspecté : la <span class=\"kw-ttt\">ponction</span> à l'aiguille ne fournit pas assez de tissu → <span class=\"kw-ttt\">médiastinoscopie</span> reste la règle.</li></ul><h4>Étiologies (médiastin moyen)</h4><ul><li><span class=\"kw-clinique\">Adénopathies</span> (<span class=\"kw-etio\">cancers bronchopulmonaires</span>, <span class=\"kw-etio\">lymphome</span>, <span class=\"kw-etio\">LLC</span>, métastases ; <span class=\"kw-etio\">sarcoïdose</span>, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">silicose</span>), <span class=\"kw-etio\">kystes bronchogéniques</span>, <span class=\"kw-etio\">paragangliomes</span>.</li></ul>"},{"id":"t-posterieur","kind":"terminal","label":"Médiastin postérieur — tumeurs neurogènes","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-imagerie\">IRM</span> essentielle pour le bilan lésionnel (reconnaître <span class=\"kw-clinique\">les</span> lésions infiltrantes).</li><li><span class=\"kw-ttt\">Ponction transpariétale</span> ou <span class=\"kw-ttt\">trans-œsophagienne échoguidée</span> ; <span class=\"kw-ttt\">chirurgie diagnostique + exérèse</span> si <span class=\"kw-clinique\">lésion</span> limitée.</li></ul><h4>Étiologies (médiastin postérieur)</h4><ul><li><span class=\"kw-etio\">Tumeurs neurogènes</span> (schwannomes, neuroblastomes, neurofibromes, paragangliomes) = <span class=\"kw-chiffre\">1/3</span> des tumeurs médiastinales ; bénignes chez l'adulte, malignes chez l'enfant.</li></ul>"}]},"cards":[{"i":"1e89d03770c5","n":207,"o":"207-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une opacité pulmonaire chez l’enfant et l’adulte","q":"Quand est-ce que la TEP au 18-FDG est indiquée dans l'exploration d'un nodule pulmonaire, et quels sont ses pièges (faux positifs/négatifs) ?","a":"<p>La TEP au 18-FDG est indiquée pour :</p><ul><li>Un <strong>nodule de nature incertaine</strong> (RVP ≈ 4 pour un nodule hypermétabolique).</li><li>Le <strong>bilan d'extension à distance</strong> d'une tumeur éligible à un traitement local.</li><li>Le <strong>staging médiastinal</strong> d'un cancer a priori opérable.</li></ul><p>Les pièges incluent :</p><ul><li><strong>Faux négatifs</strong> : Nodule &lt; 1 cm, nodule en verre dépoli pur.</li><li><strong>Faux positifs</strong> : Foyers infectieux chroniques (actinomycose, nocardiose), mycobactérioses, aspergilloses, sarcoïdose.</li><li><strong>Fixations non pathologiques</strong> : vésicale, colique, cardiaque, cérébrale.</li></ul>"},{"i":"245518895e5a","n":207,"o":"207-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une opacité pulmonaire chez l’enfant et l’adulte","q":"Quelles sont les circonstances de découverte d'une opacité pulmonaire et quel est l'intérêt de la radiographie thoracique (RXT) dans ce contexte ?","a":"<p>Les opacités pulmonaires peuvent être découvertes dans les circonstances suivantes :</p><ul><li><strong>Bilan médical orienté</strong> : pour une maladie respiratoire (pneumopathie, BPCO, toux, exposition à l'amiante) ou un bilan d'extension de cancer/maladie systémique.</li><li><strong>Découverte fortuite ou dépistage</strong> : lors d'un angioscanner des troncs supra-aortiques, d'un scanner abdominal, ou d'un dépistage opportuniste.</li></ul><p>La RXT a une <strong>place marginale</strong> dans le diagnostic de cancer pulmonaire. Elle n'a <strong>aucune place</strong> pour la découverte d'un micronodule ou d'un nodule, ni dans le dépistage. Une RXT normale n'élimine pas un diagnostic de cancer, bien que cela reste rare (&lt; 5 % des cas de cancer avéré).</p>"},{"i":"4c8e3a7ece55","n":207,"o":"207-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une opacité pulmonaire chez l’enfant et l’adulte","q":"Comment définit-on une opacité intra-parenchymateuse et quelles sont les différentes catégories selon la taille au scanner ?","a":"<p>Une opacité intra-parenchymateuse est une opacité circonscrite, unique ou multiple, de densité solide, en verre dépoli pur ou mixte. La taille mesurée au scanner permet de distinguer :</p><ul><li>Le <strong>micronodule</strong> : &lt; 3 mm</li><li>Le <strong>nodule</strong> : 3 – 30 mm</li><li>La <strong>masse</strong> : &gt; 3 cm</li></ul>"},{"i":"96128680c74b","n":207,"o":"207-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une opacité pulmonaire chez l’enfant et l’adulte","q":"Quel est l'examen morphologique pivot pour le diagnostic d'une opacité pulmonaire, et quelles informations fournit-il ?","a":"<p>L'<strong>imagerie TDM thoracique injectée</strong> est l'examen pivot du diagnostic d'une opacité pulmonaire. Elle fournit les informations suivantes :</p><ul><li><strong>Topographie</strong> : centrale/hilaire ou périphérique.</li><li><strong>Caractérisation</strong> : systématisée/rétractile ou non, rapports avec la paroi ou les structures avoisinantes.</li><li><strong>Imagerie MIP</strong> : permet un meilleur dénombrement des nodules par sommation des coupes.</li><li><strong>Facteurs associés</strong> : recherche de plaques pleurales asbestosiques ou d'adénopathies médiastinales.</li></ul>"},{"i":"c183dfc91444","n":207,"o":"207-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une opacité pulmonaire chez l’enfant et l’adulte","q":"Quelle est la technique de référence pour le diagnostic histopathologique d'une lésion pulmonaire centrale versus périphérique ?","a":"<p>La technique de référence dépend de la localisation de la lésion :</p><ul><li>Pour une <strong>lésion centrale</strong> (tiers central, autour de la carène) : la <strong>fibroscopie bronchique</strong> avec biopsies bronchiques (minimum 3-5 + biopsies systématiques de l'éperon et de la carène) est privilégiée.</li><li>Pour une <strong>lésion périphérique</strong> (tiers périphérique) : la <strong>ponction-biopsie transpariétale à l'aiguille</strong> (sous TDM, parfois échoguidée si contact pariétal) est à privilégier. Une alternative est la vidéothoracoscopie exploratrice.</li></ul>"},{"i":"d3bc362183c5","n":207,"o":"207-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une opacité pulmonaire chez l’enfant et l’adulte","q":"Pourquoi la fibroscopie bronchique est-elle quasi systématique en cas de suspicion de cancer bronchique, même si la lésion est périphérique et qu'elle peut être normale ?","a":"<p>La fibroscopie bronchique est quasi systématique car elle ne sert pas uniquement à atteindre la lésion périphérique. Elle a pour objectifs :</p><ul><li>La recherche d'éventuelles <strong>lésions radio-occultes proximales</strong>.</li><li>Le <strong>staging loco-régional</strong>.</li></ul><p>Une fibroscopie normale n'élimine <strong>PAS</strong> le diagnostic de cancer bronchique.</p>"},{"i":"03747365ba60","n":207,"o":"207-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement pleural liquidien chez l’enfant et l’adulte","q":"Quelle est la conduite diagnostique après la détection radiologique d'un épanchement pleural liquidien chez l'adulte et l'enfant ?","a":"<p>Après la détection radiologique, le diagnostic est confirmé par une <strong>ponction pleurale exploratrice</strong>. L'analyse cytochimique du liquide pleural (notamment selon les <strong>critères de Light</strong>) permet ensuite d'orienter vers l'étiologie.</p>"},{"i":"1f65e248b5e7","n":207,"o":"207-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement pleural liquidien chez l’enfant et l’adulte","q":"Comment différencier une opacité liquidienne pleurale d'une opacité pulmonaire homogène, telle qu'une atélectasie complète, chez l'adulte et l'enfant ?","a":"<p>Pour différencier une opacité liquidienne pleurale d'une opacité pulmonaire homogène (comme une atélectasie complète d'un poumon), on se base sur les critères suivants :</p><ul><li>L'épanchement pleural est <strong>non rétractile</strong>.</li><li>L'épanchement pleural est <strong>déclive</strong>, c'est-à-dire qu'il change de position avec celle du patient, contrairement à l'atélectasie.</li></ul>"},{"i":"6e8d6cc49779","n":207,"o":"207-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement pleural liquidien chez l’enfant et l’adulte","q":"Comment l'épanchement pleural liquidien se manifeste-t-il sur une radiographie thoracique (RXT) de face chez l'adulte et l'enfant ?","a":"<p>Sur une radiographie thoracique de face, l'épanchement pleural liquidien se traduit par :</p><ul><li>Une <strong>opacité homogène</strong>, <strong>déclive</strong>.</li><li>Une <strong>ligne bordante supérieure concave en haut et en dedans</strong>, appelée <strong>ligne de Damoiseau</strong>.</li><li>Un <strong>effacement du cul-de-sac pleural costo-diaphragmatique</strong>.</li><li>Si l'épanchement est abondant, un <strong>déplacement médiastinal controlatéral</strong>.</li></ul>"},{"i":"b6210b912da3","n":207,"o":"207-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement pleural liquidien chez l’enfant et l’adulte","q":"Quel est l'apport du scanner thoracique (TDM) dans le diagnostic et l'exploration d'un épanchement pleural liquidien chez l'adulte et l'enfant ?","a":"<p>Le scanner thoracique (TDM) permet de :</p><ul><li>Préciser le <strong>volume</strong> de l'épanchement.</li><li>Évaluer l'existence d'un <strong>cloisonnement</strong>.</li><li>Rechercher un <strong>épaississement pleural associé</strong> (pouvant orienter vers un mésothéliome ou une carcinose pleurale).</li><li>Détecter de petits épanchements, même < <strong>50 mL</strong>, notamment avec des coupes en décubitus latéral.</li></ul>"},{"i":"1a67153f751e","n":207,"o":"207-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement pleural gazeux chez l’enfant et l’adulte","q":"Quelle est la sémiologie radiographique d'un pneumothorax de moyenne abondance sur une radiographie thoracique de face chez l'enfant et l'adulte ?","a":"<p>Un pneumothorax de moyenne abondance se manifeste par un <strong>croissant clair avasculaire périphérique</strong> et une <strong>ligne bordante pleurale</strong> (correspondant à la plèvre viscérale décollée de la plèvre pariétale).</p>"},{"i":"37bf0f6e801a","n":207,"o":"207-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement pleural gazeux chez l’enfant et l’adulte","q":"Quel examen d'imagerie est privilégié pour le diagnostic d'un épanchement pleural gazeux (pneumothorax) chez l'enfant et l'adulte ?","a":"<p>L'examen privilégié pour le diagnostic d'un épanchement pleural gazeux est la <strong>radiographie de thorax de face</strong>.</p>"},{"i":"b8b2a83ff212","n":207,"o":"207-4","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un épanchement pleural gazeux chez l’enfant et l’adulte","q":"Quels sont les signes radiographiques d'un pneumothorax complet compressif sur une radiographie thoracique de face chez l'enfant et l'adulte ?","a":"<p>Un pneumothorax complet compressif est caractérisé par une <strong>hyperclarté diffuse</strong> de l'hémithorax atteint, un <strong>poumon entièrement décollé et rétracté au hile</strong>, et une <strong>déviation médiastinale controlatérale</strong>, signant son caractère compressif.</p>"},{"i":"8d632a085693","n":207,"o":"207-9","u":"Diagnostic positif","t":"Connaître les modalités de prescription d’une radiographie thoracique en urgence","q":"Dans quel contexte clinique la radiographie thoracique (RXT) est-elle l'examen d'imagerie de première intention en urgence ?","a":"<p>La RXT est l'examen d'imagerie de première intention en urgence devant la majorité des <strong>symptômes thoraciques</strong>, notamment en cas de détresse respiratoire aiguë, douleur thoracique, traumatisme thoracique, fièvre avec signes respiratoires, ou suspicion d'embolie pulmonaire.</p>"},{"i":"b5cb3185c494","n":207,"o":"207-9","u":"Diagnostic positif","t":"Connaître les modalités de prescription d’une radiographie thoracique en urgence","q":"Quelles sont les limites de la radiographie thoracique en urgence et les pièges diagnostiques associés ?","a":"<ul><li>Une RXT normale n'élimine pas un diagnostic urgent, notamment : une <strong>embolie pulmonaire</strong> (RXT souvent normale), une <strong>pneumonie débutante</strong> (latence radio-clinique de <strong>24-48 heures</strong>) ou une <strong>dissection aortique</strong> (élargissement médiastinal subtil).</li><li>Un cliché insuffisamment pénétré peut mener à un faux diagnostic d'opacité parenchymateuse.</li><li>Un cliché en expiration peut fausser l'évaluation et simuler une cardiomégalie.</li><li>La position couchée modifie la sémiologie pleurale (épanchement liquidien diffus au lieu de cul-de-sac) et fausse l'évaluation médiastinale.</li></ul>"},{"i":"b69f8dd601d6","n":207,"o":"207-9","u":"Diagnostic positif","t":"Connaître les modalités de prescription d’une radiographie thoracique en urgence","q":"Quelles sont les modalités pratiques de prescription d'une radiographie thoracique en urgence (incidences, position, critères de qualité) ?","a":"<ul><li><strong>Incidences :</strong> L'incidence de référence est la <strong>face postéro-antérieure (PA)</strong>. Le profil est ajouté si suspicion pleurale, médiastinale, scissurale ou rétrocardiaque. En cas de patient instable non transportable, un cliché <strong>antéro-postérieur (AP) couché</strong> au lit peut être réalisé, mais il est moins informatif.</li><li><strong>Position :</strong> Le patient doit être <strong>debout</strong>, en <strong>inspiration profonde</strong>, dos contre la plaque.</li><li><strong>Critères de qualité :</strong>\n<ul><li><strong>Inspiration :</strong> <strong>6 arcs antérieurs</strong> ou <strong>9-10 arcs postérieurs</strong> visibles.</li><li><strong>Centrage :</strong> Apophyses épineuses centrées entre les clavicules.</li><li><strong>Pénétration :</strong> Visualisation des disques intervertébraux à travers le médiastin.</li></ul></li></ul>"}]};